import { useTranslation } from 'react-i18next'
import { useThemeStore } from '../store/themeStore'
import { Heart, Activity, Droplet, TrendingUp } from 'lucide-react'

function HealthLogsPage() {
    const { t } = useTranslation()
    const theme = useThemeStore((state) => state.theme)

    const isDarkTheme = theme === 'dark' || (theme === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches)

    const healthMetrics = [
        { icon: Heart, label: t('heartRate') || 'Heart Rate', value: '72 bpm', color: '#ef4444' },
        { icon: Activity, label: t('steps') || 'Steps', value: '8,432', color: '#3b82f6' },
        { icon: Droplet, label: t('bloodPressure') || 'Blood Pressure', value: '120/80', color: '#8b5cf6' },
        { icon: TrendingUp, label: t('weight') || 'Weight', value: '75 kg', color: '#10b981' },
    ]

    return (
        <div className="p-4 sm:p-6 lg:p-8">
            <div className="mb-6">
                <h1 className="text-2xl sm:text-3xl font-bold mb-2">{t('healthLogs') || 'Health Logs'}</h1>
                <p style={{ color: isDarkTheme ? '#9ca3af' : '#6b7280' }}>
                    {t('trackYourHealth') || 'Track your health metrics and progress'}
                </p>
            </div>

            {/* Health Metrics Grid */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-8">
                {healthMetrics.map((metric, idx) => {
                    const Icon = metric.icon
                    return (
                        <div
                            key={idx}
                            className="p-4 rounded-lg border"
                            style={{
                                backgroundColor: isDarkTheme ? '#1e293b' : '#ffffff',
                                borderColor: isDarkTheme ? '#334155' : '#e5e7eb'
                            }}
                        >
                            <div className="flex items-center justify-between mb-2">
                                <span className="text-sm font-medium">{metric.label}</span>
                                <Icon className="w-5 h-5" style={{ color: metric.color }} />
                            </div>
                            <p className="text-2xl font-bold" style={{ color: metric.color }}>{metric.value}</p>
                        </div>
                    )
                })}
            </div>

            {/* Recent Logs */}
            <div
                className="rounded-lg border overflow-hidden"
                style={{
                    backgroundColor: isDarkTheme ? '#1e293b' : '#ffffff',
                    borderColor: isDarkTheme ? '#334155' : '#e5e7eb'
                }}
            >
                <div className="p-4 border-b" style={{ borderColor: isDarkTheme ? '#334155' : '#e5e7eb' }}>
                    <h2 className="font-semibold">{t('recentLogs') || 'Recent Logs'}</h2>
                </div>
                <div className="overflow-x-auto">
                    <table className="w-full text-sm">
                        <thead style={{ backgroundColor: isDarkTheme ? '#0f172a' : '#f9fafb' }}>
                            <tr>
                                <th className="px-4 py-3 text-left font-semibold">{t('date') || 'Date'}</th>
                                <th className="px-4 py-3 text-left font-semibold">{t('metric') || 'Metric'}</th>
                                <th className="px-4 py-3 text-left font-semibold">{t('value') || 'Value'}</th>
                                <th className="px-4 py-3 text-left font-semibold">{t('status') || 'Status'}</th>
                            </tr>
                        </thead>
                        <tbody>
                            {[
                                { date: '2025-01-01', metric: 'Heart Rate', value: '72 bpm', status: 'Normal' },
                                { date: '2025-01-01', metric: 'Steps', value: '8,432', status: 'Good' },
                            ].map((log, idx) => (
                                <tr key={idx} style={{ borderTop: `1px solid ${isDarkTheme ? '#334155' : '#e5e7eb'}` }}>
                                    <td className="px-4 py-3">{log.date}</td>
                                    <td className="px-4 py-3">{log.metric}</td>
                                    <td className="px-4 py-3">{log.value}</td>
                                    <td className="px-4 py-3 text-green-500">{log.status}</td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    )
}

export default HealthLogsPage
