import { useState } from 'react'
import { useTranslation } from 'react-i18next'
import { useThemeStore } from '../../store/themeStore'
import { useAuthStore } from '../../store/authStore'
import { 
    Bell, Moon, Sun, ChevronDown
} from 'lucide-react'

const TopBar = ({ sidebarCollapsed, isMobile, isPublic = false }) => {
    const { t, i18n } = useTranslation()
    const theme = useThemeStore((state) => state.theme)
    const setTheme = useThemeStore((state) => state.setTheme)
    const { user } = useAuthStore()
    const [languageMenuOpen, setLanguageMenuOpen] = useState(false)

    const isDarkTheme = theme === 'dark' || (theme === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches)
    const isRtl = i18n.language === 'ar'

    return (
        <div
            className="h-16 px-4 sm:px-6 lg:px-8 flex items-center justify-between border-b fixed top-0 z-30 backdrop-blur-md transition-all duration-200"
            style={{
                backgroundColor: isDarkTheme ? 'rgba(15, 23, 42, 0.98)' : 'rgba(255, 255, 255, 0.98)',
                borderColor: isDarkTheme ? '#1e293b' : '#e5e7eb',
                ...(isRtl ? {
                    right: !isMobile && !isPublic ? (sidebarCollapsed ? '80px' : '256px') : '0',
                    left: '0',
                    width: !isMobile && !isPublic ? `calc(100% - ${sidebarCollapsed ? '80px' : '256px'})` : '100%'
                } : {
                    left: !isMobile && !isPublic ? (sidebarCollapsed ? '80px' : '256px') : '0',
                    right: '0',
                    width: !isMobile && !isPublic ? `calc(100% - ${sidebarCollapsed ? '80px' : '256px'})` : '100%'
                })
            }}
        >
            {/* Left: Menu toggle & Logo */}
            <div className="flex items-center gap-4">
                <img src="/om-logo.png" alt="Logo" className="w-8 h-8 rounded-full" />
                <h1 className="text-lg sm:text-xl md:text-2xl font-bold bg-gradient-to-r from-blue-500 to-cyan-500 bg-clip-text text-transparent">
                    {t('common.appName') || 'OMCare'}
                </h1>
            </div>

            {/* Right: Notifications, Messages, Theme, Language, AI Chat */}
            <div className="flex items-center gap-2 sm:gap-3 lg:gap-4">
                {/* Notifications (Private Only) */}
                {!isPublic && (
                    <button
                        className="p-2 rounded-lg hover:bg-opacity-50 relative transition-colors duration-200 group"
                        style={{ backgroundColor: isDarkTheme ? '#0f172a' : '#f3f4f6' }}
                        title={t('ui.notificationsBell') || 'Notifications'}
                    >
                        <Bell className="w-5 h-5 sm:w-6 sm:h-6" />
                        <span className="absolute top-1 right-1 w-2 h-2 bg-red-500 rounded-full animate-pulse" />
                    </button>
                )}

                {/* Theme Toggle */}
                <button
                    onClick={() => setTheme(isDarkTheme ? 'light' : 'dark')}
                    className="p-2 rounded-lg hover:bg-opacity-50 transition-colors duration-200"
                    style={{ backgroundColor: isDarkTheme ? '#0f172a' : '#f3f4f6' }}
                    title={isDarkTheme ? t('theme.light') || 'Light' : t('theme.dark') || 'Dark'}
                >
                    {isDarkTheme ? <Sun className="w-5 h-5 sm:w-6 sm:h-6" /> : <Moon className="w-5 h-5 sm:w-6 sm:h-6" />}
                </button>

                {/* Language Dropdown */}
                <div className="relative">
                    <button
                        onClick={() => setLanguageMenuOpen(!languageMenuOpen)}
                        className="p-2 rounded-lg hover:bg-opacity-50 transition-colors duration-200 flex items-center gap-1"
                        style={{ backgroundColor: isDarkTheme ? '#0f172a' : '#f3f4f6' }}
                        title={t('language.label') || 'Language'}
                    >
                        <span className="text-xs sm:text-sm font-semibold">{i18n.language.toUpperCase()}</span>
                        <ChevronDown className={`w-4 h-4 transition-transform duration-200 ${languageMenuOpen ? 'rotate-180' : ''}`} />
                    </button>

                    {/* Language Dropdown Menu */}
                    {languageMenuOpen && (
                        <div
                            className="absolute top-full right-0 mt-2 w-40 rounded-lg shadow-xl border overflow-hidden z-50"
                            style={{
                                backgroundColor: isDarkTheme ? '#1e293b' : '#ffffff',
                                borderColor: isDarkTheme ? '#334155' : '#e5e7eb',
                                boxShadow: isDarkTheme ? '0 20px 40px rgba(0, 0, 0, 0.3)' : '0 20px 40px rgba(0, 0, 0, 0.1)'
                            }}
                        >
                            <button
                                onClick={() => {
                                    i18n.changeLanguage('en')
                                    setLanguageMenuOpen(false)
                                }}
                                className={`w-full px-4 py-3 text-left font-medium text-sm transition-colors duration-200 flex items-center gap-2 hover:bg-blue-500 hover:text-white`}
                                style={{
                                    backgroundColor: i18n.language === 'en' ? '#3b82f6' : 'transparent',
                                    color: i18n.language === 'en' ? '#ffffff' : isDarkTheme ? '#ffffff' : '#0f172a'
                                }}
                            >
                                <span>🇬🇧</span> {t('language.english')}
                            </button>
                            <button
                                onClick={() => {
                                    i18n.changeLanguage('ar')
                                    setLanguageMenuOpen(false)
                                }}
                                className={`w-full px-4 py-3 text-left font-medium text-sm transition-colors duration-200 flex items-center gap-2 hover:bg-blue-500 hover:text-white`}
                                style={{
                                    backgroundColor: i18n.language === 'ar' ? '#3b82f6' : 'transparent',
                                    color: i18n.language === 'ar' ? '#ffffff' : isDarkTheme ? '#ffffff' : '#0f172a'
                                }}
                            >
                                <span>🇸🇦</span> {t('language.arabic')}
                            </button>
                        </div>
                    )}
                </div>

                {/* User Avatar (Private Only) */}
                {!isPublic && (
                    <div
                        className="w-8 h-8 sm:w-10 sm:h-10 rounded-full flex items-center justify-center font-bold text-xs sm:text-sm cursor-pointer transition-all duration-200 hover:shadow-md"
                        style={{ backgroundColor: '#3b82f6', color: '#ffffff', boxShadow: '0 4px 12px rgba(59, 130, 246, 0.2)' }}
                        title={user?.fullName}
                    >
                        {user?.fullName ? (user.fullName.firstName ? user.fullName.firstName.charAt(0).toUpperCase() : user.fullName.charAt(0).toUpperCase()) : 'U'}
                    </div>
                )}
            </div>
        </div>
    )
}

export default TopBar
