import { useTranslation } from 'react-i18next'
import { useThemeStore } from '../store/themeStore'
import { useAuthStore } from '../store/authStore'
import { Check } from 'lucide-react'

function PremiumPage() {
    const { t } = useTranslation()
    const theme = useThemeStore((state) => state.theme)
    const { isPremium, updatePremium } = useAuthStore()

    const isDarkTheme = theme === 'dark' || (theme === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches)

    const plans = [
        {
            name: 'Basic',
            price: 'Free',
            features: [t('basicFeature1') || 'Basic appointments', t('basicFeature2') || 'Limited consultations']
        },
        {
            name: 'Premium',
            price: '$9.99/month',
            features: [t('premiumFeature1') || 'Unlimited appointments', t('premiumFeature2') || 'Priority support', t('premiumFeature3') || 'Advanced analytics'],
            recommended: true
        },
        {
            name: 'Professional',
            price: '$19.99/month',
            features: [t('proFeature1') || 'Everything in Premium', t('proFeature2') || 'API access', t('proFeature3') || 'Custom integrations']
        }
    ]

    return (
        <div className="p-4 sm:p-6 lg:p-8">
            <div className="mb-8">
                <h1 className="text-2xl sm:text-3xl md:text-4xl font-bold mb-2">{t('premium.title') || 'Premium Plans'}</h1>
                <p style={{ color: isDarkTheme ? '#9ca3af' : '#6b7280' }}>
                    {t('premium.description') || 'Upgrade your account to unlock exclusive features'}
                </p>
            </div>

            {isPremium && (
                <div
                    className="p-4 rounded-lg mb-6 text-green-700"
                    style={{ backgroundColor: '#dcfce7', borderLeft: '4px solid #16a34a' }}
                >
                    {t('premium.alreadyPremium') || 'You already have a premium plan!'}
                </div>
            )}

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                {plans.map((plan) => (
                    <div
                        key={plan.name}
                        className={`rounded-lg border transition-transform duration-200 hover:scale-105 ${plan.recommended ? 'md:scale-105 shadow-lg' : ''}`}
                        style={{
                            backgroundColor: isDarkTheme ? '#1e293b' : '#ffffff',
                            borderColor: plan.recommended ? '#3b82f6' : (isDarkTheme ? '#334155' : '#e5e7eb'),
                            borderWidth: plan.recommended ? '2px' : '1px'
                        }}
                    >
                        {plan.recommended && (
                            <div className="px-6 py-2 text-center text-sm font-semibold text-white" style={{ backgroundColor: '#3b82f6' }}>
                                {t('premium.recommended') || 'Recommended'}
                            </div>
                        )}

                        <div className="p-6">
                            <h3 className="text-xl font-semibold mb-2">{plan.name}</h3>
                            <p className="text-3xl font-bold mb-4 text-blue-500">{plan.price}</p>

                            <ul className="space-y-3 mb-6">
                                {plan.features.map((feature, idx) => (
                                    <li key={idx} className="flex items-center gap-2">
                                        <Check className="w-5 h-5 text-green-500" />
                                        <span className="text-sm">{feature}</span>
                                    </li>
                                ))}
                            </ul>

                            <button
                                onClick={() => updatePremium(true)}
                                disabled={plan.name === 'Basic' || isPremium}
                                className={`w-full px-4 py-2 rounded-lg font-medium text-sm transition-colors duration-200 ${
                                    plan.name === 'Basic' || isPremium ? 'opacity-50 cursor-not-allowed' : 'hover:bg-blue-600'
                                }`}
                                style={{
                                    backgroundColor: '#3b82f6',
                                    color: '#ffffff'
                                }}
                            >
                                {isPremium && plan.name !== 'Basic' ? t('premium.current') || 'Current' : t('premium.upgrade') || 'Upgrade'}
                            </button>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    )
}

export default PremiumPage
