import { create } from 'zustand'
import { persist } from 'zustand/middleware'
import authApi from '../api/authApi'

/**
 * @file authStore.js
 * @description Zustand store for authentication state management (user, token, role).
 * @module store/authStore
 */
export const useAuthStore = create(
    persist(
        (set, get) => ({
            // User state
            user: null,
            isAuthenticated: false,
            role: null, // 'patient', 'doctor', 'receptionist'
            isPremium: false,
            loading: false,
            error: null,

            // Auth actions
            login: async (identifier, password) => {
                set({ loading: true, error: null });
                try {
                    const res = await authApi.login({ identifier, password });
                    const { token, user } = res.data;
                    localStorage.setItem('token', token);
                    set({
                        user,
                        isAuthenticated: true,
                        role: user.role,
                        isPremium: user.isPremium || false,
                        loading: false
                    });
                    return true;
                } catch (err) {
                    set({ loading: false, error: err.response?.data?.msg || 'Login failed' });
                    return false;
                }
            },

            signup: async (userData) => {
                set({ loading: true, error: null });
                try {
                    const res = await authApi.register(userData);
                    const { token, user } = res.data;
                    localStorage.setItem('token', token);
                    set({
                        user,
                        isAuthenticated: true,
                        role: user.role,
                        isPremium: user.isPremium || false,
                        loading: false
                    });
                    return true;
                } catch (err) {
                    set({ loading: false, error: err.response?.data?.msg || 'Signup failed' });
                    return false;
                }
            },

            logout: () => {
                localStorage.removeItem('token');
                set({
                    user: null,
                    isAuthenticated: false,
                    role: null,
                    isPremium: false
                });
            },

            checkAuth: async () => {
                const token = localStorage.getItem('token');
                if (!token) return;
                try {
                    const res = await authApi.getMe();
                    set({ user: res.data, isAuthenticated: true, role: res.data.role, isPremium: res.data.isPremium });
                } catch (err) {
                    localStorage.removeItem('token');
                    set({ user: null, isAuthenticated: false, role: null });
                }
            },

            updatePremium: (isPremium) => set((state) => ({
                isPremium,
                user: state.user ? { ...state.user, isPremium } : null
            })),

            updateRole: (role) => set((state) => ({
                role,
                user: state.user ? { ...state.user, role } : null
            })),

            updateUser: (userData) => set((state) => ({
                user: { ...state.user, ...userData }
            }))
        }),
        {
            name: 'auth-store',
            partialize: (state) => ({
                user: state.user,
                isAuthenticated: state.isAuthenticated,
                role: state.role,
                isPremium: state.isPremium
            })
        }
    )
)
