import { useState, useEffect } from 'react'
import { Outlet, useLocation } from 'react-router-dom'
import { useTranslation } from 'react-i18next'
import { useThemeStore } from '../store/themeStore'
import Sidebar from '../components/layout/Sidebar'
import TopBar from '../components/layout/TopBar'
import BottomBar from '../components/layout/BottomBar'
import AIChat from '../components/layout/AIChat'

function MainLayout() {
    const { i18n } = useTranslation()
    const theme = useThemeStore((state) => state.theme)
    const [sidebarCollapsed, setSidebarCollapsed] = useState(false)
    const [isMobile, setIsMobile] = useState(window.innerWidth < 768)
    const location = useLocation()
    
    // Derived state
    const isDarkTheme = theme === 'dark' || (theme === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches)
    const isRtl = i18n.language === 'ar'

    useEffect(() => {
        const handleResize = () => setIsMobile(window.innerWidth < 768)
        window.addEventListener('resize', handleResize)
        return () => window.removeEventListener('resize', handleResize)
    }, [])

    return (
        <div
            className="flex h-screen overflow-hidden transition-colors duration-200"
            style={{
                backgroundColor: isDarkTheme ? '#0f172a' : '#f9fafb',
                color: isDarkTheme ? '#ffffff' : '#0f172a'
            }}
        >
            {/* Sidebar (Desktop Only) */}
            <Sidebar 
                collapsed={sidebarCollapsed} 
                setCollapsed={setSidebarCollapsed}
                isMobile={isMobile}
            />

            {/* Main Content Area */}
            <div className="flex-1 flex flex-col overflow-hidden relative">
                <TopBar 
                    sidebarCollapsed={sidebarCollapsed} 
                    isMobile={isMobile}
                />
                <div 
                    className={`flex-1 overflow-y-auto pt-16 ${isMobile ? 'pb-16' : ''}`}
                    style={{ scrollBehavior: 'smooth' }}
                >
                    <Outlet />
                </div>

                {/* Bottom Navigation (Mobile Only) */}
                {isMobile && <BottomBar />}
            </div>

            {/* Floating UI Elements */}
            {location.pathname !== '/messages' && <AIChat isMobile={isMobile} isRtl={isRtl} />}
        </div>
    )
}

export default MainLayout
