import { useState } from 'react'
import { useTranslation } from 'react-i18next'
import { useThemeStore } from '../store/themeStore'
import { useAuthStore } from '../store/authStore'
import { Moon, Sun, Globe } from 'lucide-react'

function SettingsPage() {
    const { t, i18n } = useTranslation()
    const theme = useThemeStore((state) => state.theme)
    const setTheme = useThemeStore((state) => state.setTheme)
    const { user, updateUser } = useAuthStore()

    const isDarkTheme = theme === 'dark' || (theme === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches)
    const [email, setEmail] = useState(user?.email || '')
    const [firstName, setFirstName] = useState(user?.fullName?.firstName || '')
    const [lastName, setLastName] = useState(user?.fullName?.lastName || '')

    return (
        <div className="p-4 sm:p-6 lg:p-8 max-w-2xl">
            <h1 className="text-2xl sm:text-3xl font-bold mb-6">{t('navigation.settings') || 'Settings'}</h1>

            {/* Profile Settings */}
            <div
                className="p-6 rounded-lg border mb-6"
                style={{
                    backgroundColor: isDarkTheme ? '#1e293b' : '#ffffff',
                    borderColor: isDarkTheme ? '#334155' : '#e5e7eb'
                }}
            >
                <h2 className="text-lg font-semibold mb-4">{t('settings.profileSettings') || 'Profile Settings'}</h2>
                <div className="space-y-4">
                    <div className="flex gap-4">
                        <div className="flex-1">
                            <label className="block text-sm font-medium mb-1">{t('firstName') || 'First Name'}</label>
                            <input
                                type="text"
                                value={firstName}
                                onChange={(e) => setFirstName(e.target.value)}
                                className="w-full px-4 py-2 rounded-lg border"
                                style={{
                                    backgroundColor: isDarkTheme ? '#0f172a' : '#f3f4f6',
                                    borderColor: isDarkTheme ? '#334155' : '#e5e7eb',
                                    color: isDarkTheme ? '#ffffff' : '#0f172a'
                                }}
                            />
                        </div>
                        <div className="flex-1">
                            <label className="block text-sm font-medium mb-1">{t('lastName') || 'Last Name'}</label>
                            <input
                                type="text"
                                value={lastName}
                                onChange={(e) => setLastName(e.target.value)}
                                className="w-full px-4 py-2 rounded-lg border"
                                style={{
                                    backgroundColor: isDarkTheme ? '#0f172a' : '#f3f4f6',
                                    borderColor: isDarkTheme ? '#334155' : '#e5e7eb',
                                    color: isDarkTheme ? '#ffffff' : '#0f172a'
                                }}
                            />
                        </div>
                    </div>
                    <div>
                        <label className="block text-sm font-medium mb-1">{t('email') || 'Email'}</label>
                        <input
                            type="email"
                            value={email}
                            onChange={(e) => setEmail(e.target.value)}
                            className="w-full px-4 py-2 rounded-lg border"
                            style={{
                                backgroundColor: isDarkTheme ? '#0f172a' : '#f3f4f6',
                                borderColor: isDarkTheme ? '#334155' : '#e5e7eb',
                                color: isDarkTheme ? '#ffffff' : '#0f172a'
                            }}
                        />
                    </div>
                    <button className="w-full px-4 py-2 rounded-lg bg-blue-500 text-white hover:bg-blue-600">
                        {t('saveChanges') || 'Save Changes'}
                    </button>
                </div>
            </div>

            {/* Theme Settings */}
            <div
                className="p-6 rounded-lg border mb-6"
                style={{
                    backgroundColor: isDarkTheme ? '#1e293b' : '#ffffff',
                    borderColor: isDarkTheme ? '#334155' : '#e5e7eb'
                }}
            >
                <h2 className="text-lg font-semibold mb-4">{t('settings.themeSettings') || 'Theme Settings'}</h2>
                <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                    {['light', 'dark', 'system'].map((t_mode) => (
                        <button
                            key={t_mode}
                            onClick={() => setTheme(t_mode)}
                            className={`p-4 rounded-lg border-2 transition-colors`}
                            style={{
                                backgroundColor: theme === t_mode ? '#eff6ff' : (isDarkTheme ? '#0f172a' : '#ffffff'),
                                borderColor: theme === t_mode ? '#3b82f6' : (isDarkTheme ? '#334155' : '#e5e7eb')
                            }}
                        >
                            <div className="flex justify-center mb-2">
                                {t_mode === 'light' && <Sun className="w-6 h-6" />}
                                {t_mode === 'dark' && <Moon className="w-6 h-6" />}
                                {t_mode === 'system' && <Globe className="w-6 h-6" />}
                            </div>
                            <span className="text-sm font-medium capitalize">{t(t_mode) || t_mode}</span>
                        </button>
                    ))}
                </div>
            </div>

            {/* Language Settings */}
            <div
                className="p-6 rounded-lg border"
                style={{
                    backgroundColor: isDarkTheme ? '#1e293b' : '#ffffff',
                    borderColor: isDarkTheme ? '#334155' : '#e5e7eb'
                }}
            >
                <h2 className="text-lg font-semibold mb-4">{t('language') || 'Language'}</h2>
                <div className="space-y-2">
                    {['en', 'ar'].map((lang) => (
                        <button
                            key={lang}
                            onClick={() => i18n.changeLanguage(lang)}
                            className="w-full p-3 rounded-lg text-left hover:opacity-80 transition-opacity"
                            style={{
                                backgroundColor: i18n.language === lang ? '#3b82f6' : (isDarkTheme ? '#0f172a' : '#f3f4f6'),
                                color: i18n.language === lang ? '#ffffff' : (isDarkTheme ? '#d1d5db' : '#0f172a')
                            }}
                        >
                            {lang === 'en' ? 'English' : 'العربية'}
                        </button>
                    ))}
                </div>
            </div>
        </div>
    )
}

export default SettingsPage
