import { useState } from 'react'
import { Search, UserPlus, MoreVertical, Pin, Archive, Trash2 } from 'lucide-react'
import { useTranslation } from 'react-i18next'

const ChatSidebar = ({ 
    conversations, 
    selectedChatId, 
    onSelectChat, 
    searchQuery, 
    setSearchQuery, 
    userSearchResults,
    onStartNewChat,
    onlineUsers,
    getOtherParticipant,
    showMobileChat,
    isDarkTheme,
    onUpdateConversation
}) => {
    const { t } = useTranslation()
    const [activeMenuId, setActiveMenuId] = useState(null)

    const isUserOnline = (userId) => onlineUsers.has(userId)

    const handleMenuAction = (e, action, conv) => {
        e.stopPropagation()
        setActiveMenuId(null)
        if (action === 'pin') {
            onUpdateConversation(conv._id, { isPinned: !conv.isPinned })
        } else if (action === 'archive') {
            onUpdateConversation(conv._id, { isArchived: !conv.isArchived })
        }
    }

    return (
        <div
            className={`${showMobileChat ? 'hidden md:flex' : 'flex'} w-full md:w-80 lg:w-96 border-r flex-col bg-white dark:bg-slate-900 transition-all duration-300`}
            style={{ borderColor: isDarkTheme ? '#1e293b' : '#e5e7eb' }}
        >
            <div className="p-4 border-b dark:border-slate-800">
                <h2 className="text-xl font-bold mb-4">{t('navigation.messages') || 'Messages'}</h2>
                <div className="relative">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                    <input
                        type="text"
                        placeholder={t('ui.searchMessages') || 'Search conversations...'}
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        className="w-full pl-9 pr-4 py-2.5 rounded-xl border text-sm transition-all focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none"
                        style={{
                            backgroundColor: isDarkTheme ? '#0f172a' : '#f8fafc',
                            borderColor: isDarkTheme ? '#334155' : '#e2e8f0',
                            color: isDarkTheme ? '#ffffff' : '#0f172a'
                        }}
                    />
                </div>
            </div>
            
            <div className="flex-1 overflow-y-auto p-2 space-y-1" onClick={() => setActiveMenuId(null)}>
                {/* Search Results */}
                {searchQuery && userSearchResults.length > 0 && (
                    <div className="mb-4">
                        <div className="px-3 py-2 text-xs font-semibold text-gray-500 uppercase tracking-wider">
                            {t('ui.searchResults') || 'Search Results'}
                        </div>
                        {userSearchResults.map((searchUser) => {
                            const displayName = `${searchUser.fullName?.firstName || ''} ${searchUser.fullName?.lastName || ''}`.trim() || searchUser.email
                            
                            return (
                                <button
                                    key={searchUser._id}
                                    onClick={() => onStartNewChat(searchUser._id)}
                                    className="w-full p-3 rounded-xl text-left transition-all duration-200 flex gap-3 hover:bg-blue-50 dark:hover:bg-blue-900/20"
                                >
                                    <div className="relative flex-shrink-0">
                                        <div className="w-12 h-12 rounded-full flex items-center justify-center text-lg font-bold text-white bg-gradient-to-br from-green-400 to-green-600">
                                            {displayName.charAt(0).toUpperCase()}
                                        </div>
                                        <div className="absolute bottom-0 right-0 w-6 h-6 rounded-full bg-white dark:bg-slate-900 flex items-center justify-center">
                                            <UserPlus className="w-4 h-4 text-green-500" />
                                        </div>
                                    </div>
                                    <div className="flex-1 min-w-0">
                                        <div className="font-semibold truncate text-gray-900 dark:text-gray-100">
                                            {displayName}
                                        </div>
                                        <p className="text-sm text-gray-500 truncate">
                                            {searchUser.email || searchUser.phone}
                                        </p>
                                        <span className="text-xs text-gray-400 capitalize">
                                            {searchUser.role}
                                        </span>
                                    </div>
                                </button>
                            )
                        })}
                        <div className="border-t dark:border-slate-700 my-2"></div>
                    </div>
                )}

                {searchQuery && userSearchResults.length === 0 && searchQuery.length >= 2 && (
                    <div className="text-center py-8 text-gray-400">
                        <Search className="w-12 h-12 mx-auto mb-2 opacity-50" />
                        <p>{t('ui.noResults') || 'No users found'}</p>
                    </div>
                )}

                {/* Conversations List */}
                {!searchQuery && conversations.map((conv) => {
                    const otherUser = getOtherParticipant(conv)
                    const isOnline = otherUser && isUserOnline(otherUser._id)
                    const displayName = otherUser ? 
                        `${otherUser.fullName?.firstName || ''} ${otherUser.fullName?.lastName || ''}`.trim() || otherUser.email :
                        conv.name || 'Unknown'

                    return (
                        <div
                            key={conv._id}
                            onClick={() => onSelectChat(conv._id)}
                            className={`w-full p-3 rounded-xl text-left transition-all duration-200 flex gap-3 cursor-pointer group relative ${
                                selectedChatId === conv._id 
                                ? 'bg-blue-50 dark:bg-blue-900/20' 
                                : 'hover:bg-gray-50 dark:hover:bg-slate-800'
                            } ${conv.isPinned ? 'border-l-4 border-blue-500' : ''}`}
                        >
                            <div className="relative flex-shrink-0">
                                <div className="w-12 h-12 rounded-full flex items-center justify-center text-lg font-bold text-white bg-gradient-to-br from-blue-400 to-blue-600">
                                    {displayName.charAt(0).toUpperCase()}
                                </div>
                                {isOnline && (
                                    <span className="absolute bottom-0 right-0 w-3 h-3 rounded-full border-2 border-white dark:border-slate-900 bg-green-500"></span>
                                )}
                            </div>
                            <div className="flex-1 min-w-0 pr-6">
                                <div className="flex justify-between items-baseline mb-1">
                                    <span className={`font-semibold truncate ${
                                        selectedChatId === conv._id ? 'text-blue-600 dark:text-blue-400' : 'text-gray-900 dark:text-gray-100'
                                    }`}>
                                        {displayName}
                                    </span>
                                    <span className="text-xs text-gray-500">
                                        {conv.lastMessage ? new Date(conv.updatedAt).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}) : ''}
                                    </span>
                                </div>
                                <p className="text-sm text-gray-500 truncate">
                                    {conv.isPinned && <Pin className="w-3 h-3 inline mr-1 text-blue-500" />}
                                    {conv.lastMessage?.content || t('chat.startConversation')}
                                </p>
                            </div>

                            {/* Options Button */}
                            <button
                                onClick={(e) => {
                                    e.stopPropagation()
                                    setActiveMenuId(activeMenuId === conv._id ? null : conv._id)
                                }}
                                className={`absolute right-2 top-1/2 -translate-y-1/2 p-1.5 rounded-full hover:bg-gray-200 dark:hover:bg-slate-700 text-gray-400 hover:text-gray-600 dark:hover:text-gray-200 transition-opacity ${activeMenuId === conv._id ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}
                            >
                                <MoreVertical className="w-4 h-4" />
                            </button>

                            {/* Dropdown Menu */}
                            {activeMenuId === conv._id && (
                                <div 
                                    className="absolute right-0 top-full mt-1 w-48 bg-white dark:bg-slate-800 rounded-lg shadow-xl border dark:border-slate-700 z-50 overflow-hidden"
                                    onClick={(e) => e.stopPropagation()}
                                >
                                    <button 
                                        onClick={(e) => handleMenuAction(e, 'pin', conv)}
                                        className="w-full text-left px-4 py-2.5 text-sm hover:bg-gray-50 dark:hover:bg-slate-700 flex items-center gap-2 text-gray-700 dark:text-gray-200"
                                    >
                                        <Pin className="w-4 h-4" /> 
                                        {conv.isPinned ? t('chat.unpin') || 'Unpin' : t('chat.pin') || 'Pin'}
                                    </button>
                                    <button 
                                        onClick={(e) => handleMenuAction(e, 'archive', conv)}
                                        className="w-full text-left px-4 py-2.5 text-sm hover:bg-gray-50 dark:hover:bg-slate-700 flex items-center gap-2 text-gray-700 dark:text-gray-200"
                                    >
                                        <Archive className="w-4 h-4" />
                                        {conv.isArchived ? t('chat.unarchive') || 'Unarchive' : t('chat.archive') || 'Archive'}
                                    </button>
                                </div>
                            )}
                        </div>
                    )
                })}
            </div>
        </div>
    )
}

export default ChatSidebar
