import { useTranslation } from 'react-i18next'
import { useThemeStore } from '../store/themeStore'
import { useAuthStore } from '../store/authStore'
import { Calendar, Clock, MapPin, Phone, CheckCircle, XCircle, MoreVertical } from 'lucide-react'

function AppointmentsPage() {
    const { t } = useTranslation()
    const theme = useThemeStore((state) => state.theme)
    const { role } = useAuthStore()

    const isDarkTheme = theme === 'dark' || (theme === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches)

    const appointments = [
        { id: 1, doctor: 'Dr. Ahmed', specialist: 'Cardiologist', date: '2025-01-15', time: '02:00 PM', location: 'Heart Center, Building A', phone: '+1234567890', status: 'upcoming', avatar: 'A' },
        { id: 2, doctor: 'Dr. Sarah', specialist: 'Dermatologist', date: '2025-01-20', time: '10:00 AM', location: 'Skin Clinic, Room 302', phone: '+1234567891', status: 'confirmed', avatar: 'S' },
        { id: 3, doctor: 'Dr. Michael', specialist: 'General Practitioner', date: '2024-12-28', time: '09:30 AM', location: 'Main Hospital', phone: '+1234567892', status: 'completed', avatar: 'M' },
    ]

    const getStatusColor = (status) => {
        switch(status) {
            case 'confirmed': return 'text-green-500 bg-green-500/10'
            case 'upcoming': return 'text-blue-500 bg-blue-500/10'
            case 'completed': return 'text-gray-500 bg-gray-500/10'
            case 'cancelled': return 'text-red-500 bg-red-500/10'
            default: return 'text-gray-500 bg-gray-500/10'
        }
    }

    return (
        <div className="p-4 sm:p-6 lg:p-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-8">
                <div>
                    <h1 className="text-3xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-600 to-cyan-500">
                        {t('navigation.appointments') || 'Appointments'}
                    </h1>
                    <p className="text-sm mt-1" style={{ color: isDarkTheme ? '#94a3b8' : '#64748b' }}>
                        Manage your scheduled visits and history
                    </p>
                </div>
                {role !== 'receptionist' && (
                    <button className="px-6 py-2.5 rounded-xl bg-gradient-to-r from-blue-500 to-cyan-500 text-white font-semibold shadow-lg shadow-blue-500/25 hover:shadow-blue-500/40 hover:scale-105 transition-all duration-200">
                        {t('ui.bookAppointment') || 'Book Appointment'}
                    </button>
                )}
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {appointments.map((apt) => (
                    <div
                        key={apt.id}
                        className="rounded-2xl p-6 relative group transition-all duration-300 hover:shadow-xl hover:-translate-y-1"
                        style={{
                            backgroundColor: isDarkTheme ? '#1e293b' : '#ffffff',
                            border: `1px solid ${isDarkTheme ? '#334155' : '#e2e8f0'}`,
                            boxShadow: isDarkTheme ? '0 4px 6px -1px rgba(0, 0, 0, 0.2)' : '0 4px 6px -1px rgba(0, 0, 0, 0.05)'
                        }}
                    >
                        <div className="flex justify-between items-start mb-4">
                            <div className="flex gap-4">
                                <div className={`w-12 h-12 rounded-full flex items-center justify-center text-lg font-bold text-white shadow-md bg-gradient-to-br ${
                                    apt.status === 'completed' ? 'from-gray-400 to-gray-600' : 'from-blue-400 to-blue-600'
                                }`}>
                                    {apt.avatar}
                                </div>
                                <div>
                                    <h3 className="font-bold text-lg leading-tight" style={{ color: isDarkTheme ? '#f1f5f9' : '#1e293b' }}>{apt.doctor}</h3>
                                    <p className="text-xs font-medium text-blue-500">{apt.specialist}</p>
                                </div>
                            </div>
                            <span className={`px-3 py-1 rounded-full text-xs font-bold uppercase tracking-wider ${getStatusColor(apt.status)}`}>
                                {apt.status}
                            </span>
                        </div>

                        <div className="space-y-3 mb-6">
                            <div className="flex items-center gap-3 text-sm" style={{ color: isDarkTheme ? '#cbd5e1' : '#475569' }}>
                                <Calendar className="w-4 h-4 text-blue-500" />
                                <span className="font-medium">{new Date(apt.date).toLocaleDateString(undefined, { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric' })}</span>
                            </div>
                            <div className="flex items-center gap-3 text-sm" style={{ color: isDarkTheme ? '#cbd5e1' : '#475569' }}>
                                <Clock className="w-4 h-4 text-blue-500" />
                                <span className="font-medium">{apt.time}</span>
                            </div>
                            <div className="flex items-center gap-3 text-sm" style={{ color: isDarkTheme ? '#cbd5e1' : '#475569' }}>
                                <MapPin className="w-4 h-4 text-blue-500" />
                                <span>{apt.location}</span>
                            </div>
                            <div className="flex items-center gap-3 text-sm" style={{ color: isDarkTheme ? '#cbd5e1' : '#475569' }}>
                                <Phone className="w-4 h-4 text-blue-500" />
                                <span>{apt.phone}</span>
                            </div>
                        </div>

                        {apt.status !== 'completed' && (
                            <div className="pt-4 border-t flex gap-3" style={{ borderColor: isDarkTheme ? '#334155' : '#f1f5f9' }}>
                                <button className="flex-1 py-2 rounded-lg bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400 text-sm font-semibold hover:bg-blue-100 dark:hover:bg-blue-900/40 transition-colors">
                                    {t('ui.reschedule') || 'Reschedule'}
                                </button>
                                <button className="flex-1 py-2 rounded-lg bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 text-sm font-semibold hover:bg-red-100 dark:hover:bg-red-900/40 transition-colors">
                                    {t('common.cancel') || 'Cancel'}
                                </button>
                            </div>
                        )}
                        {apt.status === 'completed' && (
                            <div className="pt-4 border-t" style={{ borderColor: isDarkTheme ? '#334155' : '#f1f5f9' }}>
                                <button className="w-full py-2 rounded-lg border border-gray-200 dark:border-gray-700 text-gray-600 dark:text-gray-400 text-sm font-semibold hover:bg-gray-50 dark:hover:bg-gray-800 transition-colors">
                                    View Summary
                                </button>
                            </div>
                        )}
                    </div>
                ))}
            </div>
        </div>
    )
}

export default AppointmentsPage
