import { useState, useEffect, useRef } from 'react'
import { useTranslation } from 'react-i18next'
import { useThemeStore } from '../store/themeStore'
import { useAuthStore } from '../store/authStore'
import messageApi from '../api/messageApi'
import userApi from '../api/userApi'
import io from 'socket.io-client'
import ChatSidebar from '../components/chat/ChatSidebar'
import ChatWindow from '../components/chat/ChatWindow'
import CallModal from '../components/chat/CallModal'

/**
 * @file MessagesPage.jsx
 * @description Main Chat Page. Orchestrates chat sidebar, window, socket connection, WebRTC calls, and recordings.
 * @module pages/MessagesPage
 */
function MessagesPage() {
    const { t } = useTranslation()
    const theme = useThemeStore((state) => state.theme)
    const { user } = useAuthStore()
    
    // UI State
    const [selectedChatId, setSelectedChatId] = useState(null)
    const [showMobileChat, setShowMobileChat] = useState(false)
    const [searchQuery, setSearchQuery] = useState('')
    const [userSearchResults, setUserSearchResults] = useState([])
    
    // Message State
    const [conversations, setConversations] = useState([])
    const [messages, setMessages] = useState({})
    const [typingUsers, setTypingUsers] = useState(new Set())
    const [onlineUsers, setOnlineUsers] = useState(new Set())

    // Call State
    const [callModalOpen, setCallModalOpen] = useState(false)
    const [incomingCall, setIncomingCall] = useState(null)
    const [isIncoming, setIsIncoming] = useState(false)
    const [isVideoCall, setIsVideoCall] = useState(false)

    // Recording State
    const [isRecording, setIsRecording] = useState(false)
    const [mediaRecorder, setMediaRecorder] = useState(null)
    const [recordingTime, setRecordingTime] = useState(0)
    const timerRef = useRef(null)

    const socketRef = useRef()
    const typingTimeoutRef = useRef(null)

    const isDarkTheme = theme === 'dark' || (theme === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches)

    const scrollToMessage = (messageId) => {
        const element = document.getElementById(`message-${messageId}`)
        if (element) {
            element.scrollIntoView({ behavior: 'smooth', block: 'center' })
            element.classList.add('bg-blue-50', 'dark:bg-blue-900/20', 'transition-colors', 'duration-500')
            setTimeout(() => {
                element.classList.remove('bg-blue-50', 'dark:bg-blue-900/20', 'transition-colors', 'duration-500')
            }, 2000)
        }
    }

    const activeChat = conversations.find(c => c._id === selectedChatId)
    const chatMessages = activeChat ? (messages[activeChat._id] || []) : []

    // Socket.IO Connection
    useEffect(() => {
        if (!user) return

        socketRef.current = io(import.meta.env.VITE_SOCKET_URL || 'http://localhost:5000', {
            withCredentials: true
        })

        socketRef.current.emit('user_online', (user?._id || user?.id))

        socketRef.current.on('receive_message', (message) => {
            setMessages(prev => ({
                ...prev,
                [message.conversation]: [...(prev[message.conversation] || []), message]
            }))
            
            // Update conversation last message and sort
            setConversations(prev => {
                const updated = prev.map(c => 
                    c._id === message.conversation 
                        ? { ...c, lastMessage: message, updatedAt: new Date() }
                        : c
                )
                return updated.sort((a, b) => new Date(b.updatedAt) - new Date(a.updatedAt))
            })
        })

        socketRef.current.on('user_typing', ({ userId, conversationId }) => {
            if (conversationId === selectedChatId) {
                setTypingUsers(prev => new Set(prev).add(userId))
            }
        })

        socketRef.current.on('user_stop_typing', ({ userId }) => {
            setTypingUsers(prev => {
                const newSet = new Set(prev)
                newSet.delete(userId)
                return newSet
            })
        })

        socketRef.current.on('user_status_change', ({ userId, status }) => {
            setOnlineUsers(prev => {
                const newSet = new Set(prev)
                if (status === 'online') {
                    newSet.add(userId)
                } else {
                    newSet.delete(userId)
                }
                return newSet
            })
        })

        // WebRTC Signaling
        socketRef.current.on('call_user', (data) => {
            setIncomingCall(data)
            setIsIncoming(true)
            setIsVideoCall(data.isVideo)
            setCallModalOpen(true)
        })

        socketRef.current.on('call_ended', () => {
            setCallModalOpen(false)
            setIncomingCall(null)
            setIsIncoming(false)
        })

        return () => {
            socketRef.current?.disconnect()
        }
    }, [user])

    // Load conversations
    useEffect(() => {
        if (!user) return
        loadConversations()
    }, [user])

    // Join/leave conversation rooms
    useEffect(() => {
        if (selectedChatId && socketRef.current) {
            socketRef.current.emit('join_conversation', selectedChatId)
            loadMessages(selectedChatId)
            
            return () => {
                socketRef.current.emit('leave_conversation', selectedChatId)
            }
        }
    }, [selectedChatId])

    // Recording timer
    useEffect(() => {
        if (isRecording) {
            timerRef.current = setInterval(() => setRecordingTime(prev => prev + 1), 1000)
        } else {
            clearInterval(timerRef.current)
            setRecordingTime(0)
        }
        return () => clearInterval(timerRef.current)
    }, [isRecording])

    const loadConversations = async () => {
        try {
            const res = await messageApi.getConversations()
            setConversations(res.data)
        } catch (err) {
            console.error('Failed to load conversations:', err)
        }
    }

    const loadMessages = async (conversationId) => {
        try {
            const res = await messageApi.getMessages(conversationId)
            setMessages(prev => ({ ...prev, [conversationId]: res.data }))
            
            await messageApi.markAsRead(conversationId)
            socketRef.current?.emit('message_read', { userId: (user?._id || user?.id), conversationId })
        } catch (err) {
            console.error('Failed to load messages:', err)
        }
    }

    const searchUsers = async (query) => {
        if (!query.trim() || query.trim().length < 2) {
            setUserSearchResults([])
            return
        }
        
        try {
            const res = await userApi.searchUsers(query)
            setUserSearchResults(res.data)
        } catch (err) {
            console.error('Search failed:', err)
            setUserSearchResults([])
        }
    }

    const startNewChat = async (userId) => {
        try {
            const res = await messageApi.getOrCreateConversation(userId, 'direct')
            if (!res.data || !res.data._id) throw new Error('Invalid conversation response')

            const newConversation = res.data
            setConversations(prev => {
                const exists = prev.find(c => c._id === newConversation._id)
                return exists ? prev : [newConversation, ...prev]
            })

            setSelectedChatId(newConversation._id)
            setShowMobileChat(true)
            setSearchQuery('')
            setUserSearchResults([])
        } catch (err) {
            console.error('Failed to start chat:', err)
            alert('Failed to start conversation.')
        }
    }

    const handleSendMessage = async (content, replyToMsg) => {
        if (!content.trim() || !selectedChatId) return

        const messageData = {
            content,
            type: 'text',
            replyTo: replyToMsg?._id
        }

        try {
            const res = await messageApi.sendMessage(selectedChatId, messageData)
            
            setMessages(prev => ({
                ...prev,
                [selectedChatId]: [...(prev[selectedChatId] || []), res.data]
            }))

            socketRef.current?.emit('send_message', {
                conversationId: selectedChatId,
                ...res.data
            })
            
            socketRef.current?.emit('typing_stop', { userId: (user?._id || user?.id), conversationId: selectedChatId })
            
            // Update conversation list last message immediately and sort
            setConversations(prev => {
                const updated = prev.map(c => 
                    c._id === selectedChatId 
                        ? { ...c, lastMessage: res.data, updatedAt: new Date() }
                        : c
                )
                return updated.sort((a, b) => new Date(b.updatedAt) - new Date(a.updatedAt))
            })

        } catch (err) {
            console.error('Failed to send message:', err)
        }
    }

    const handleFileUpload = async (e) => {
        const file = e.target.files[0]
        if (!file || !selectedChatId) return

        try {
            const uploadRes = await messageApi.uploadFile(file)
            const messageData = {
                content: uploadRes.data.fileName,
                type: uploadRes.data.type,
                mediaUrl: uploadRes.data.url,
                fileName: uploadRes.data.fileName,
                fileSize: uploadRes.data.fileSize
            }
            const res = await messageApi.sendMessage(selectedChatId, messageData)
            setMessages(prev => ({
                ...prev,
                [selectedChatId]: [...(prev[selectedChatId] || []), res.data]
            }))
            socketRef.current?.emit('send_message', {
                conversationId: selectedChatId,
                ...res.data
            })
        } catch (err) {
            console.error('File upload failed:', err)
        }
    }

    const handleDeleteMessage = async (messageId, forEveryone) => {
        try {
            await messageApi.deleteMessage(messageId, forEveryone)
            setMessages(prev => ({
                ...prev,
                [selectedChatId]: prev[selectedChatId].map(m =>
                    m._id === messageId
                        ? forEveryone 
                            ? { ...m, isDeleted: true, content: t('chat.messageDeleted'), mediaUrl: null }
                            : m
                        : m
                ).filter(m => forEveryone || m._id !== messageId)
            }))
        } catch (err) {
            console.error('Delete failed:', err)
        }
    }

    const startRecording = async () => {
        try {
            const stream = await navigator.mediaDevices.getUserMedia({ audio: true })
            const recorder = new MediaRecorder(stream)
            setMediaRecorder(recorder)
            const chunks = []
            
            recorder.ondataavailable = (e) => chunks.push(e.data)
            recorder.onstop = async () => {
                const blob = new Blob(chunks, { type: 'audio/webm' })
                const file = new File([blob], 'voice-message.webm', { type: 'audio/webm' })
                
                try {
                    const uploadRes = await messageApi.uploadFile(file)
                    const messageData = {
                        content: 'Voice message',
                        type: 'audio',
                        mediaUrl: uploadRes.data.url,
                        fileName: uploadRes.data.fileName,
                        fileSize: uploadRes.data.fileSize
                    }
                    const res = await messageApi.sendMessage(selectedChatId, messageData)
                    setMessages(prev => ({
                        ...prev,
                        [selectedChatId]: [...(prev[selectedChatId] || []), res.data]
                    }))
                    socketRef.current?.emit('send_message', {
                        conversationId: selectedChatId,
                        ...res.data
                    })
                } catch (err) {
                    console.error('Voice message failed:', err)
                }
            }
            
            recorder.start()
            setIsRecording(true)
        } catch (err) {
            console.error('Microphone access denied:', err)
        }
    }

    const stopRecording = () => {
        mediaRecorder?.stop()
        setIsRecording(false)
        mediaRecorder?.stream.getTracks().forEach(track => track.stop())
    }

    const getOtherParticipant = (conversation) => {
        if (!conversation || !user) return null
        const currentUserId = (user?._id || user?.id || '').toString()
        return conversation.participants?.find(p => (p._id || p.id).toString() !== currentUserId)
    }

    const handleUpdateConversation = async (conversationId, data) => {
        try {
            const res = await messageApi.updateConversation(conversationId, data)
            setConversations(prev => prev.map(c => 
                c._id === conversationId ? { ...c, ...res.data } : c
            ))
        } catch (err) {
            console.error('Failed to update conversation:', err)
        }
    }

    // Call Logic
    const startCall = (withVideo) => {
        const other = getOtherParticipant(activeChat)
        if (!other) {
            console.warn('Cannot start call: no participant found')
            return
        }
        setIsVideoCall(withVideo)
        setIsIncoming(false)
        setCallModalOpen(true)
    }

    return (
        <div className="flex h-[calc(100vh-4rem-1px)] overflow-hidden bg-gray-50 dark:bg-slate-900 border-t dark:border-slate-800 relative">
            <ChatSidebar 
                conversations={conversations}
                selectedChatId={selectedChatId}
                onSelectChat={(id) => {
                    setSelectedChatId(id)
                    setShowMobileChat(true)
                }}
                searchQuery={searchQuery}
                setSearchQuery={(q) => {
                    setSearchQuery(q)
                    searchUsers(q)
                }}
                userSearchResults={userSearchResults}
                onStartNewChat={startNewChat}
                onlineUsers={onlineUsers}
                getOtherParticipant={getOtherParticipant}
                showMobileChat={showMobileChat}
                isDarkTheme={isDarkTheme}
                onUpdateConversation={handleUpdateConversation}
            />

            <ChatWindow 
                activeChat={activeChat}
                messages={chatMessages}
                user={user}
                isUserOnline={(uid) => onlineUsers.has(uid)}
                onSendMessage={handleSendMessage}
                onFileUpload={handleFileUpload}
                onStartRecording={startRecording}
                onStopRecording={stopRecording}
                isRecording={isRecording}
                recordingTime={recordingTime}
                onScrollToMessage={scrollToMessage}
                onBack={() => {
                    setShowMobileChat(false)
                    setSelectedChatId(null)
                }}
                onDeleteMessage={handleDeleteMessage}
                onCallClick={startCall}
                typingUsers={typingUsers}
                onUpdateConversation={handleUpdateConversation}
            />

            {callModalOpen && activeChat && (
                <CallModal 
                    isOpen={callModalOpen}
                    onClose={() => setCallModalOpen(false)}
                    socket={socketRef.current}
                    user={user}
                    targetUser={incomingCall ? { _id: incomingCall.from, fullName: { firstName: incomingCall.name } } : getOtherParticipant(activeChat)}
                    isIncoming={isIncoming}
                    incomingCallSignal={incomingCall?.signal}
                    isVideoCall={isVideoCall}
                />
            )}
        </div>
    )
}

export default MessagesPage
