import { useRef, useEffect, useState } from 'react'
import { Send, Phone, Video, MoreVertical, Paperclip, Mic, Image as ImageIcon, StopCircle, ArrowLeft, X } from 'lucide-react'
import { useTranslation } from 'react-i18next'
import MessageBubble from './MessageBubble'

const ChatWindow = ({ 
    activeChat, 
    messages, 
    user, 
    isUserOnline, 
    onSendMessage, 
    onFileUpload, 
    onStartRecording, 
    onStopRecording, 
    isRecording, 
    recordingTime, 
    onBack,
    onDeleteMessage,
    onCallClick,
    typingUsers,
    onScrollToMessage,
    onUpdateConversation
}) => {
    const { t } = useTranslation()
    const [newMessage, setNewMessage] = useState('')
    const [replyingTo, setReplyingTo] = useState(null)
    const [showAttachMenu, setShowAttachMenu] = useState(false)
    const [showHeaderMenu, setShowHeaderMenu] = useState(false)
    const [selectedImage, setSelectedImage] = useState(null)
    
    const messagesEndRef = useRef(null)
    const textareaRef = useRef(null)
    const typingTimeoutRef = useRef(null)

    // Auto-scroll
    useEffect(() => {
        messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
    }, [messages])

    if (!activeChat) return (
        <div className="flex-1 flex flex-col items-center justify-center text-gray-400 bg-white/50 dark:bg-slate-900/50 backdrop-blur-sm">
            <div className="w-20 h-20 bg-gray-100 dark:bg-slate-800 rounded-full flex items-center justify-center mb-4">
                <Send className="w-8 h-8 opacity-50" />
            </div>
            <p>{t('chat.selectContact')}</p>
        </div>
    )

    const getOtherParticipant = (conversation) => {
        if (!conversation || !user) return null
        const currentUserId = (user?._id || user?.id || '').toString()
        return conversation.participants?.find(p => (p._id || p.id).toString() !== currentUserId)
    }

    const otherUser = getOtherParticipant(activeChat)
    const displayName = otherUser ? 
        `${otherUser.fullName?.firstName || ''} ${otherUser.fullName?.lastName || ''}`.trim() || otherUser.email :
        activeChat.name || 'Unknown'
    const isOnline = otherUser && isUserOnline(otherUser._id)

    const handleSend = () => {
        if (!newMessage.trim()) return
        onSendMessage(newMessage, replyingTo)
        setNewMessage('')
        setReplyingTo(null)
    }

    const handleKeyPress = (e) => {
        if (e.key === 'Enter' && !e.shiftKey) {
            e.preventDefault()
            handleSend()
        }
    }

    const handleTyping = (e) => {
        setNewMessage(e.target.value)
        // Parent should handle socket emission for typing if needed, 
        // but for now we just handle local state. 
        // Ideally we pass "onTyping" prop.
    }

    return (
        <div className="flex-1 flex flex-col bg-white/50 dark:bg-slate-900/50 backdrop-blur-sm relative w-full h-full">
            {/* Chat Header */}
            <div className="h-16 border-b flex items-center justify-between px-4 bg-white dark:bg-slate-900 border-gray-200 dark:border-slate-800">
                <div className="flex items-center gap-3">
                    <button onClick={onBack} className="md:hidden p-2 -ml-2 hover:bg-gray-100 dark:hover:bg-slate-800 rounded-full">
                        <ArrowLeft className="w-5 h-5" />
                    </button>
                    
                    <div className="w-10 h-10 rounded-full flex items-center justify-center text-white font-bold bg-gradient-to-br from-blue-400 to-blue-600">
                        {displayName.charAt(0).toUpperCase()}
                    </div>
                    <div>
                        <h3 className="font-bold text-gray-900 dark:text-gray-100">{displayName}</h3>
                        <p className="text-xs text-gray-500">
                            {isOnline ? t('chat.online') : t('chat.offline')}
                        </p>
                    </div>
                </div>
                
                <div className="flex items-center gap-1">
                    <button onClick={() => onCallClick(false)} className="p-2 rounded-full hover:bg-gray-100 dark:hover:bg-slate-800 text-gray-500">
                        <Phone className="w-5 h-5" />
                    </button>
                    <button onClick={() => onCallClick(true)} className="p-2 rounded-full hover:bg-gray-100 dark:hover:bg-slate-800 text-gray-500">
                        <Video className="w-5 h-5" />
                    </button>
                    <div className="relative">
                        <button 
                            onClick={() => setShowHeaderMenu(!showHeaderMenu)}
                            className="p-2 rounded-full hover:bg-gray-100 dark:hover:bg-slate-800 text-gray-500"
                        >
                            <MoreVertical className="w-5 h-5" />
                        </button>
                        {showHeaderMenu && (
                            <>
                                <div className="fixed inset-0 z-10" onClick={() => setShowHeaderMenu(false)}></div>
                                <div className="absolute right-0 top-full mt-2 w-48 bg-white dark:bg-slate-800 rounded-lg shadow-xl border dark:border-slate-700 z-20 overflow-hidden">
                                    <button 
                                        onClick={() => {
                                            onUpdateConversation(activeChat._id, { isArchived: !activeChat.isArchived })
                                            setShowHeaderMenu(false)
                                            if (!activeChat.isArchived) onBack() // Go back if archiving
                                        }}
                                        className="w-full text-left px-4 py-3 text-sm hover:bg-gray-50 dark:hover:bg-slate-700 text-gray-700 dark:text-gray-200"
                                    >
                                        {activeChat.isArchived ? t('chat.unarchive') || 'Unarchive Chat' : t('chat.archive') || 'Archive Chat'}
                                    </button>
                                </div>
                            </>
                        )}
                    </div>
                </div>
            </div>

            {/* Messages Feed */}
            <div className="flex-1 overflow-y-auto p-4 space-y-6">
                {messages.map((msg) => (
                    <MessageBubble 
                        key={msg._id} 
                        message={msg} 
                        onReply={setReplyingTo}
                        onReplyClick={onScrollToMessage}
                        onDelete={onDeleteMessage}
                        onImageClick={setSelectedImage}
                    />
                ))}
                
                {typingUsers.size > 0 && (
                    <div className="flex items-center gap-2 text-sm text-gray-500">
                        <div className="flex gap-1">
                            <span className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0ms' }}></span>
                            <span className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '150ms' }}></span>
                            <span className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '300ms' }}></span>
                        </div>
                        <span>{t('chat.typing')}</span>
                    </div>
                )}
                
                <div ref={messagesEndRef} />
            </div>

            {/* Lightbox for images */}
            {selectedImage && (
                <div className="fixed inset-0 z-[60] bg-black/90 flex items-center justify-center p-4" onClick={() => setSelectedImage(null)}>
                    <button className="absolute top-4 right-4 p-2 bg-white/10 hover:bg-white/20 rounded-full text-white">
                        <X className="w-6 h-6" />
                    </button>
                    <img src={selectedImage} alt="Full view" className="max-w-full max-h-full rounded-lg shadow-2xl" onClick={(e) => e.stopPropagation()} />
                </div>
            )}

            {/* Input Area */}
            <div className="p-3 md:p-4 bg-white dark:bg-slate-900 border-t border-gray-200 dark:border-slate-800">
                {replyingTo && (
                    <div className="flex items-center justify-between bg-gray-50 dark:bg-slate-800 p-2 rounded-t-lg border-b dark:border-slate-700 mb-2">
                        <div className="flex items-center gap-2 text-sm text-gray-500 truncate">
                            <span>{t('chat.replyingTo')} <span className="font-bold">{replyingTo.sender?.fullName?.firstName}</span></span>
                        </div>
                        <button onClick={() => setReplyingTo(null)}><X className="w-4 h-4" /></button>
                    </div>
                )}

                <div className="flex gap-2 md:gap-3 items-end">
                    <div className="relative">
                        <button 
                            onClick={() => setShowAttachMenu(!showAttachMenu)}
                            className={`p-2 rounded-full transition-colors ${showAttachMenu ? 'bg-blue-100 text-blue-600' : 'hover:bg-gray-100 dark:hover:bg-slate-800 text-gray-400'}`}
                        >
                            <Paperclip className="w-5 h-5" />
                        </button>
                        {showAttachMenu && (
                            <>
                                <div className="fixed inset-0 z-10" onClick={() => setShowAttachMenu(false)}></div>
                                <div className="absolute bottom-12 left-0 z-20 bg-white dark:bg-slate-800 shadow-xl rounded-xl border dark:border-slate-700 p-2 flex flex-col gap-1 min-w-[160px]">
                                    <label className="flex items-center gap-3 p-2 hover:bg-gray-100 dark:hover:bg-slate-700 rounded-lg cursor-pointer">
                                        <div className="w-8 h-8 rounded-full bg-purple-100 flex items-center justify-center text-purple-600"><ImageIcon className="w-4 h-4"/></div>
                                        <span className="text-sm font-medium">{t('chat.chooseImage')}</span>
                                        <input type="file" accept="image/*" className="hidden" onChange={(e) => { onFileUpload(e); setShowAttachMenu(false); }} />
                                    </label>
                                    <label className="flex items-center gap-3 p-2 hover:bg-gray-100 dark:hover:bg-slate-700 rounded-lg cursor-pointer">
                                        <div className="w-8 h-8 rounded-full bg-pink-100 flex items-center justify-center text-pink-600"><Video className="w-4 h-4"/></div>
                                        <span className="text-sm font-medium">{t('chat.chooseVideo')}</span>
                                        <input type="file" accept="video/*" className="hidden" onChange={(e) => { onFileUpload(e); setShowAttachMenu(false); }} />
                                    </label>
                                    <label className="flex items-center gap-3 p-2 hover:bg-gray-100 dark:hover:bg-slate-700 rounded-lg cursor-pointer">
                                        <div className="w-8 h-8 rounded-full bg-blue-100 flex items-center justify-center text-blue-600"><Paperclip className="w-4 h-4"/></div>
                                        <span className="text-sm font-medium">{t('chat.chooseFile')}</span>
                                        <input type="file" className="hidden" onChange={(e) => { onFileUpload(e); setShowAttachMenu(false); }} />
                                    </label>
                                </div>
                            </>
                        )}
                    </div>

                    <div className="flex-1 relative">
                        <textarea
                            ref={textareaRef}
                            value={newMessage}
                            onChange={handleTyping}
                            onKeyDown={handleKeyPress}
                            placeholder={isRecording ? `${t('chat.recording')}... (${recordingTime}s)` : (t('chat.typeMessage') || 'Type a message...')}
                            className="w-full px-4 py-3 rounded-xl border text-sm transition-all focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none resize-none disabled:bg-red-50 disabled:text-red-500 dark:bg-slate-800 dark:border-slate-700 dark:text-white"
                            disabled={isRecording}
                            rows={1}
                            style={{
                                maxHeight: '120px',
                                minHeight: '48px'
                            }}
                            dir="auto"
                        />
                        {isRecording && (
                            <div className="absolute right-2 top-1/2 -translate-y-1/2 flex items-center gap-2">
                                <div className="w-2 h-2 rounded-full bg-red-500 animate-pulse"></div>
                            </div>
                        )}
                    </div>
                    
                    {newMessage.trim() ? (
                        <button 
                            onClick={handleSend}
                            className="p-3 rounded-xl bg-blue-500 hover:bg-blue-600 text-white shadow-lg shadow-blue-500/30 transition-all hover:scale-105 active:scale-95"
                        >
                            <Send className="w-5 h-5" />
                        </button>
                    ) : (
                        isRecording ? (
                            <button 
                                onClick={onStopRecording}
                                className="p-3 rounded-xl bg-red-500 hover:bg-red-600 text-white shadow-lg shadow-red-500/30 transition-all hover:scale-105 active:scale-95"
                            >
                                <StopCircle className="w-5 h-5" />
                            </button>
                        ) : (
                            <button 
                                onClick={onStartRecording}
                                className="p-3 rounded-xl bg-gray-100 dark:bg-slate-800 hover:bg-gray-200 dark:hover:bg-slate-700 text-gray-500 transition-all"
                            >
                                <Mic className="w-5 h-5" />
                            </button>
                        )
                    )}
                </div>
            </div>
        </div>
    )
}

export default ChatWindow
