import { useNavigate, useLocation } from 'react-router-dom'
import { useTranslation } from 'react-i18next'
import { useAuthStore } from '../../store/authStore'
import { useThemeStore } from '../../store/themeStore'
import { 
    ChevronLeft, ChevronRight, LogOut, 
    Home, MessageSquare, Calendar, Heart, 
    Users, Crown, Settings 
} from 'lucide-react'

const Sidebar = ({ 
    collapsed, 
    setCollapsed, 
    isMobile, 
    setOpen 
}) => {
    const navigate = useNavigate()
    const location = useLocation()
    const { t, i18n } = useTranslation()
    const { role, logout, isPremium } = useAuthStore()
    const theme = useThemeStore((state) => state.theme)
    
    // Derived state directly from stores/hooks to match MainLayout logic
    const isDarkTheme = theme === 'dark' || (theme === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches)
    const isRtl = i18n.language === 'ar'
    const isActive = (path) => location.pathname === path

    // Reconstruct menu items logic here to keep it self-contained or passed via props.
    // Since it relies on auth/role, keeping it here is fine.
    const getMenuItems = () => {
        const baseItems = [
            { id: 'dashboard', label: t('navigation.dashboard') || 'Dashboard', icon: Home, path: '/dashboard', roles: ['patient', 'doctor', 'receptionist'] },
            { id: 'messages', label: t('navigation.messages') || 'Messages', icon: MessageSquare, path: '/messages', roles: ['patient', 'doctor', 'receptionist'] },
            { id: 'appointments', label: t('navigation.appointments') || 'Appointments', icon: Calendar, path: '/appointments', roles: ['patient', 'doctor', 'receptionist'] },
        ]

        const roleSpecific = {
            patient: [
                { id: 'health_logs', label: t('navigation.healthLogs') || 'Health Logs', icon: Heart, path: '/health-logs', roles: ['patient'] },
            ],
            doctor: [
                { id: 'patients', label: t('navigation.patients') || 'Patients', icon: Users, path: '/patients', roles: ['doctor', 'receptionist'] },
            ],
            receptionist: [
                { id: 'patients', label: t('navigation.patients') || 'Patients', icon: Users, path: '/patients', roles: ['doctor', 'receptionist'] },
            ]
        }

        const allItems = [
            ...baseItems,
            ...(roleSpecific[role] || []),
            { id: 'premium', label: t('navigation.premium') || 'Premium', icon: Crown, path: '/premium', roles: ['patient', 'doctor', 'receptionist'], badge: !isPremium ? 'New' : null },
            { id: 'settings', label: t('navigation.settings') || 'Settings', icon: Settings, path: '/settings', roles: ['patient', 'doctor', 'receptionist'] },
        ]

        return allItems.filter(item => item.roles.includes(role))
    }

    const menuItems = getMenuItems()

    const handleLogout = () => {
        logout()
        navigate('/login')
    }

    if (isMobile) return null // Sidebar is hidden on mobile unless used as overlay, but code structure suggests "Sidebar - Desktop Only" block.

    return (
        <div
            className={`relative transition-all duration-300 flex-shrink-0 ${
                collapsed ? 'w-20' : 'w-64'
            } flex flex-col h-screen`}
            style={{
                backgroundColor: isDarkTheme ? '#1e293b' : '#ffffff',
                borderRight: `1px solid ${isDarkTheme ? '#334155' : '#e5e7eb'}`
            }}
        >
            {/* Collapse/Expand Button */}
            <div className="p-2 flex justify-end">
                <button
                    onClick={() => setCollapsed(!collapsed)}
                    className="p-2 rounded-lg hover:bg-opacity-50 transition-colors duration-200"
                    style={{ backgroundColor: isDarkTheme ? '#0f172a' : '#f3f4f6' }}
                    title={collapsed ? t('navigation.expand') || 'Expand' : t('navigation.collapse') || 'Collapse'}
                >
                    {isRtl ? (
                        collapsed ? <ChevronLeft className="w-5 h-5" /> : <ChevronRight className="w-5 h-5" />
                    ) : (
                        collapsed ? <ChevronRight className="w-5 h-5" /> : <ChevronLeft className="w-5 h-5" />
                    )}
                </button>
            </div>

            {/* Sidebar Content */}
            <div className="flex-1 overflow-x-hidden overflow-y-auto px-2 py-4 space-y-2">
                {menuItems.map((item) => (
                    <button
                        key={item.id}
                        onClick={() => {
                            navigate(item.path)
                            if (setOpen) setOpen(false)
                        }}
                        className={`w-full flex items-center gap-3 px-3 py-3 rounded-lg text-sm font-medium transition-all duration-200 relative group hover:shadow-md ${
                            collapsed ? 'justify-center' : ''
                        }`}
                        style={{
                            backgroundColor: isActive(item.path) 
                                ? 'linear-gradient(135deg, #0ea5e9 0%, #06b6d4 100%)' 
                                : isDarkTheme ? '#0f172a' : '#f3f4f6',
                            color: isActive(item.path) ? '#666' : isDarkTheme ? '#ddd' : '#64748b',
                            boxShadow: isActive(item.path) ? '0 4px 12px rgba(14, 165, 233, 0.3)' : 'none'
                        }}
                        title={collapsed ? item.label : ''}
                    >
                        <item.icon className="w-5 h-5 flex-shrink-0" />
                        {!collapsed && (
                            <>
                                <span className="flex-1 text-left">{item.label}</span>
                                {item.badge && (
                                    <span className="text-xs bg-red-500 text-white px-2 py-1 rounded-full ml-auto">
                                        {item.badge}
                                    </span>
                                )}
                            </>
                        )}
                        
                        {/* Tooltip for collapsed state */}
                        {collapsed && (
                            <div className="absolute left-full ml-2 px-2 py-1 bg-gray-900 text-white text-xs rounded opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap z-10 pointer-events-none">
                                {item.label}
                            </div>
                        )}
                    </button>
                ))}
            </div>

            {/* Sidebar Footer */}
            <div
                className={`p-2 border-t transition-all duration-300 ${collapsed ? 'p-1' : 'p-4'}`}
                style={{ borderColor: isDarkTheme ? '#334155' : '#e5e7eb' }}
            >
                <button
                    onClick={handleLogout}
                    className={`w-full flex items-center gap-3 px-3 py-3 rounded-lg text-sm font-medium transition-all duration-200 hover:shadow-md ${
                        collapsed ? 'justify-center' : ''
                    }`}
                    style={{
                        backgroundColor: '#dc2626',
                        color: '#ffffff'
                    }}
                    title={collapsed ? t('navigation.logout') || 'Logout' : ''}
                >
                    <LogOut className="w-5 h-5 flex-shrink-0" />
                    {!collapsed && (
                        <span className="text-left">{t('navigation.logout') || 'Logout'}</span>
                    )}
                </button>
            </div>
        </div>
    )
}

export default Sidebar
