import { useState, useEffect } from 'react'
import { useNavigate } from 'react-router-dom'
import { useTranslation } from 'react-i18next'
import { useThemeStore } from '../store/themeStore'
import { useAuthStore } from '../store/authStore'
import TopBar from '../components/layout/TopBar'
import AIChat from '../components/layout/AIChat'
import { Mail, Phone, Lock, Heart, MessageSquare, Video, Activity, Bell, MessageCircle, Bot, User } from 'lucide-react'

function LoginPage() {
    const navigate = useNavigate()
    const { t, i18n } = useTranslation()
    const theme = useThemeStore((state) => state.theme)
    const { login, signup } = useAuthStore()
    
    const [isSignup, setIsSignup] = useState(false)
    const [selectedRole, setSelectedRole] = useState('patient')
    const [loginIdentifier, setLoginIdentifier] = useState('')
    const [email, setEmail] = useState('')
    const [password, setPassword] = useState('')
    const [signupMethod, setSignupMethod] = useState('email')
    const [phone, setPhone] = useState('')
    const [firstName, setFirstName] = useState('')
    const [lastName, setLastName] = useState('')
    const [isMobile, setIsMobile] = useState(window.innerWidth < 768)

    const isDarkTheme = theme === 'dark' || (theme === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches)
    const isRtl = i18n.language === 'ar'

    useEffect(() => {
        const handleResize = () => setIsMobile(window.innerWidth < 768)
        window.addEventListener('resize', handleResize)
        return () => window.removeEventListener('resize', handleResize)
    }, [])

    const features = [
        {
            icon: Heart,
            title: t('features.appointmentManagement') || 'Appointment Management',
            description: t('features.appointmentDesc') || 'Schedule and manage appointments'
        },
        {
            icon: Activity,
            title: t('features.healthTracking') || 'Health Tracking',
            description: t('features.healthTrackingDesc') || 'Monitor your health metrics'
        },
        {
            icon: Video,
            title: t('features.telemedicine') || 'Telemedicine',
            description: t('features.telemedicineDesc') || 'Connect via secure video calls'
        },
        {
            icon: MessageSquare,
            title: t('features.secureCommunication') || 'Secure Messaging',
            description: t('features.secureCommunicationDesc') || 'Direct communication channel'
        },
        {
            icon: Bell,
            title: t('features.smartNotifications') || 'Smart Notifications',
            description: t('features.smartNotificationsDesc') || 'Timely appointment reminders'
        },
        {
            icon: Bot,
            title: t('chat.aiAssistant') || 'AI Assistant',
            description: t('chat.aiSupportDesc') || 'Chat support available'
        }
    ]

    const roles = [
        { id: 'patient', label: t('auth.patient') || 'Patient', desc: t('auth.patientDesc') || 'Personal health management' },
        { id: 'doctor', label: t('auth.doctor') || 'Doctor', desc: t('auth.doctorDesc') || 'Manage patients & appointments' },
        { id: 'receptionist', label: t('auth.receptionist') || 'Receptionist', desc: t('auth.receptionistDesc') || 'Clinic operations' }
    ]

    const handleLogin = async (e) => {
        e.preventDefault()
        if (!loginIdentifier || !password) return
        
        const success = await login(loginIdentifier, password)
        if (success) {
            navigate('/dashboard')
        }
    }

    const handleSignup = async (e) => {
        e.preventDefault()
        if (!firstName || !lastName || !email || !password) return
        
        const success = await signup({
            firstName,
            lastName,
            email,
            password,
            role: selectedRole,
            phone: signupMethod === 'phone' ? phone : null,
            signupMethod
        })
        if (success) {
            navigate('/dashboard')
        }
    }

    return (
        <div
            className="min-h-screen transition-colors duration-200"
            style={{
                backgroundColor: isDarkTheme ? '#0f172a' : '#ffffff',
                color: isDarkTheme ? '#ffffff' : '#0f172a'
            }}
        >
            {/* Shared TopBar in Public Mode */}
            <TopBar isPublic={true} isMobile={isMobile} />

            {/* Main Content with Top Padding */}
            <div className="px-4 sm:px-6 lg:px-8 py-8 lg:py-12 mt-20">
                {/* Large Logo Section */}
                <div className="text-center mb-12">
                    <div className="mb-6 flex justify-center">
                        <div
                            className="w-24 h-24 sm:w-32 sm:h-32 rounded-full flex items-center justify-center shadow-2xl relative overflow-hidden group"
                            style={{
                                background: 'linear-gradient(135deg, #3b82f6 0%, #06b6d4 100%)',
                                boxShadow: '0 20px 40px rgba(59, 130, 246, 0.3)'
                            }}
                        >
                            <div className="absolute inset-0 bg-white opacity-0 group-hover:opacity-10 transition-opacity duration-300"></div>
                            <img src="/om-logo.png" alt="OMCare Logo" className="w-full h-full object-cover p-2" />
                        </div>
                    </div>
                    <h2 className="text-3xl sm:text-4xl md:text-5xl font-bold mb-2 bg-gradient-to-r from-blue-500 via-blue-600 to-cyan-500 bg-clip-text text-transparent">
                        OMCare
                    </h2>
                    <div className="flex justify-center items-center gap-2">
                        <p className="text-center text-base sm:text-lg" style={{ color: isDarkTheme ? '#cbd5e1' : '#64748b' }}>
                            {t('auth.madeByMedestra') || 'Create your account'}
                        </p>
                        <img src="/medestra-logo.png" alt="Medestra Logo" className="w-[4%] object-cover p-2" />

                    </div>

                    {/* <p className="text-base sm:text-lg" style={{ color: isDarkTheme ? '#cbd5e1' : '#64748b' }}>
                        {isSignup ? t('auth.createAccount') || 'Create your account' : t('auth.loginTitle') || 'Login to your account'}
                    </p> */}
                </div>

                {/* Two Column Layout */}
                <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 max-w-6xl mx-auto">
                    {/* Left Side - Features (Desktop) / Hidden on Mobile when not in focus */}
                    <div className="hidden lg:block">
                        <h3 className="text-2xl font-bold mb-8 text-sky-600">{t('features.systemFeatures') || 'System Features'}</h3>
                        <div className="space-y-4">
                            {features.map((feature, idx) => {
                                const Icon = feature.icon
                                return (
                                    <div
                                        key={idx}
                                        className="flex gap-4 p-4 rounded-xl transition-all duration-300 hover:scale-105 hover:shadow-lg cursor-pointer border-l-4 group"
                                        style={{
                                            backgroundColor: isDarkTheme ? 'rgba(30, 41, 59, 0.6)' : 'rgba(243, 244, 246, 0.8)',
                                            borderColor: '#0ea5e9',
                                            boxShadow: '0 4px 12px rgba(14, 165, 233, 0.1)'
                                        }}
                                    >
                                        <div
                                            className="flex-shrink-0 w-12 h-12 rounded-lg flex items-center justify-center transition-all duration-300 group-hover:scale-110 group-hover:shadow-lg"
                                            style={{
                                                background: 'linear-gradient(135deg, #0ea5e9 0%, #06b6d4 100%)',
                                                boxShadow: '0 4px 12px rgba(14, 165, 233, 0.2)'
                                            }}
                                        >
                                            <Icon className="w-6 h-6 text-white" />
                                        </div>
                                        <div>
                                            <h4 className="font-semibold mb-1 text-gray-900 dark:text-gray-100 group-hover:text-blue-600">{feature.title}</h4>
                                            <p className="text-sm" style={{ color: isDarkTheme ? '#cbd5e1' : '#78716c' }}>
                                                {feature.description}
                                            </p>
                                        </div>
                                    </div>
                                )
                            })}
                        </div>
                    </div>

                    {/* Right Side - Form */}
                    <div>
                        <div
                            className="p-6 sm:p-8 rounded-xl shadow-2xl backdrop-blur-sm border-2 transition-all duration-300 hover:shadow-3xl"
                            style={{
                                backgroundColor: isDarkTheme ? 'rgba(30, 41, 59, 0.9)' : 'rgba(255, 255, 255, 0.95)',
                                border: `2px solid ${isDarkTheme ? '#334155' : '#e5e7eb'}`,
                                boxShadow: isDarkTheme ? '0 25px 50px rgba(0, 0, 0, 0.4)' : '0 25px 50px rgba(0, 0, 0, 0.12)'
                            }}
                        >
                            {/* Toggle Login/Signup */}
                            <div className="flex gap-2 mb-6 bg-gradient-to-r from-gray-100 to-gray-50 dark:from-slate-800 dark:to-slate-700 p-1 rounded-lg" 
                                style={{
                                    backgroundColor: isDarkTheme ? '#0f172a' : '#f3f4f6'
                                }}>
                                <button
                                    onClick={() => setIsSignup(false)}
                                    style={{
                                        backgroundColor: !isSignup ? 'linear-gradient(135deg, #3b82f6 0%, #06b6d4 100%)' : 'transparent',
                                        color: !isSignup ? '#ffffff' : isDarkTheme ? '#cbd5e1' : '#64748b',
                                        boxShadow: !isSignup ? '0 4px 12px rgba(59, 130, 246, 0.3)' : 'none'
                                    }}
                                    className="flex-1 px-4 py-2.5 rounded-md font-semibold text-sm sm:text-base transition-all duration-200 hover:shadow-md"
                                >
                                    {t('auth.login') || 'Login'}
                                </button>
                                <button
                                    onClick={() => setIsSignup(true)}
                                    style={{
                                        backgroundColor: isSignup ? 'linear-gradient(135deg, #0ea5e9 0%, #06b6d4 100%)' : 'transparent',
                                        color: isSignup ? '#ffffff' : isDarkTheme ? '#cbd5e1' : '#64748b',
                                        boxShadow: isSignup ? '0 4px 12px rgba(14, 165, 233, 0.3)' : 'none'
                                    }}
                                    className="flex-1 px-4 py-2.5 rounded-md font-semibold text-sm sm:text-base transition-all duration-200 hover:shadow-md"
                                >
                                    {t('auth.signup') || 'Signup'}
                                </button>
                            </div>

                            {/* Role Selection as Tabs */}
                            {!isSignup && (
                                <div className="mb-6 pb-6" style={{ borderBottom: `1px solid ${isDarkTheme ? '#334155' : '#e5e7eb'}` }}>
                                    <label className="block text-sm font-semibold mb-3 text-sky-600">{t('auth.selectRole') || 'Select Your Role'}</label>
                                    <div className="flex gap-2 mb-6 bg-gradient-to-r from-gray-100 to-gray-50 dark:from-slate-800 dark:to-slate-700 p-1 rounded-lg">
                                        {roles.map((role) => (
                                            <button
                                                key={role.id}
                                                onClick={() => setSelectedRole(role.id)}
                                                className={`flex-1 py-2 p-3 rounded-lg border-2 transition-all duration-200 text-left hover:shadow-md transform hover:scale-102 ${
                                                    selectedRole === role.id ? 'border-sky-500 shadow-md' : 'border-transparent'
                                                }`}
                                                style={{
                                                    backgroundColor: selectedRole === role.id 
                                                        ? (isDarkTheme ? 'rgba(14, 165, 233, 0.1)' : 'rgba(14, 165, 233, 0.05)')
                                                        : (isDarkTheme ? '#0f172a' : '#f9fafb'),
                                                    borderColor: selectedRole === role.id ? '#0ea5e9' : 'transparent',
                                                    boxShadow: selectedRole === role.id ? '0 4px 12px rgba(14, 165, 233, 0.2)' : 'none'
                                                }}
                                            >
                                                <div className="font-semibold text-sm sm:text-base capitalize text-sky-600 text-center">{role.label}</div>
                                                {/* <p className="text-xs mt-1" style={{ color: isDarkTheme ? '#94a3b8' : '#78716c' }}>
                                                    {role.desc}
                                                </p> */}
                                            </button>
                                        ))}
                                    </div>
                                </div>
                            )}

                            {/* Login Form */}
                            {!isSignup ? (
                                <form onSubmit={handleLogin} className="space-y-4">
                                    <div>
                                        <label className="block text-sm font-semibold mb-2 text-sky-600">{t('auth.emailOrPhone') || 'Email or Phone'}</label>
                                        <div className="relative group">
                                            <User className="absolute left-3 top-3 w-5 h-5 transition-colors duration-200 group-focus-within:text-sky-500" style={{ color: '#94a3b8' }} />
                                            <input
                                                type="text"
                                                value={loginIdentifier}
                                                onChange={(e) => setLoginIdentifier(e.target.value)}
                                                placeholder={t('auth.emailOrPhonePlaceholder') || 'Email or Phone Number'}
                                                className="w-full pl-10 pr-4 py-3 rounded-lg border-2 text-sm sm:text-base transition-all duration-200 focus:border-sky-500 focus:ring-2 focus:ring-sky-500 focus:ring-opacity-20 focus:outline-none"
                                                style={{
                                                    backgroundColor: isDarkTheme ? '#0f172a' : '#ffffff',
                                                    borderColor: isDarkTheme ? '#334155' : '#d1d5db',
                                                    color: isDarkTheme ? '#ffffff' : '#0f172a'
                                                }}
                                            />
                                        </div>
                                    </div>

                                    <div>
                                        <label className="block text-sm font-semibold mb-2 text-sky-600">{t('password') || 'Password'}</label>
                                        <div className="relative group">
                                            <Lock className="absolute left-3 top-3 w-5 h-5 transition-colors duration-200 group-focus-within:text-sky-500" style={{ color: '#94a3b8' }} />
                                            <input
                                                type="password"
                                                value={password}
                                                onChange={(e) => setPassword(e.target.value)}
                                                placeholder="••••••••"
                                                className="w-full pl-10 pr-4 py-3 rounded-lg border-2 text-sm sm:text-base transition-all duration-200 focus:border-sky-500 focus:ring-2 focus:ring-sky-500 focus:ring-opacity-20 focus:outline-none"
                                                style={{
                                                    backgroundColor: isDarkTheme ? '#0f172a' : '#ffffff',
                                                    borderColor: isDarkTheme ? '#334155' : '#d1d5db',
                                                    color: isDarkTheme ? '#ffffff' : '#0f172a'
                                                }}
                                            />
                                        </div>
                                    </div>

                                    <button
                                        type="submit"
                                        className="w-full px-4 py-3 rounded-lg font-semibold text-white text-sm sm:text-base transition-all duration-200 hover:shadow-lg hover:scale-105 transform bg-gradient-to-r from-sky-500 to-cyan-500 hover:from-sky-600 hover:to-cyan-600"
                                    >
                                        {t('common.startNow') || 'Login'}
                                    </button>

                                    <button
                                        type="button"
                                        onClick={() => navigate('/forgot-password')}
                                        className="w-full text-center text-sm font-medium transition-colors duration-200 hover:text-sky-600"
                                        style={{ color: '#0ea5e9' }}
                                    >
                                        {t('auth.forgotPassword') || 'Forgot password?'}
                                    </button>
                                </form>
                            ) : (
                                // Signup Form
                                <div className="space-y-4">
                                    {/* Role Selection for Signup */}
                                    <div className="mb-4 pb-4" style={{ borderBottom: `1px solid ${isDarkTheme ? '#334155' : '#e5e7eb'}` }}>
                                        <label className="block text-sm font-semibold mb-3">{t('auth.selectRole') || 'Select Your Role'}</label>
                                        <div className="flex gap-2 mb-6 bg-gradient-to-r from-gray-100 to-gray-50 dark:from-slate-800 dark:to-slate-700 p-1 rounded-lg">
                                            {roles.map((role) => (
                                                <button
                                                    key={role.id}
                                                    onClick={() => setSelectedRole(role.id)}
                                                    className={`flex-1 py-2 p-3 rounded-lg border-2 transition-all duration-200 text-left hover:shadow-md`}
                                                    style={{
                                                        backgroundColor: selectedRole === role.id 
                                                            ? (isDarkTheme ? '#334155' : '#e0e7ff')
                                                            : (isDarkTheme ? '#0f172a' : '#f3f4f6'),
                                                        borderColor: selectedRole === role.id ? '#3b82f6' : 'transparent'
                                                    }}
                                                >
                                                    <div className="font-medium text-sm sm:text-base capitalize text-center">{role.label}</div>
                                                    {/* <p className="text-xs mt-1" style={{ color: isDarkTheme ? '#9ca3af' : '#6b7280' }}>
                                                        {role.desc}
                                                    </p> */}
                                                </button>
                                            ))}
                                        </div>
                                    </div>

                                    {/* Signup Method Selection */}
                                    <div className="flex gap-2 p-2 rounded-lg" style={{ backgroundColor: isDarkTheme ? '#0f172a' : '#f3f4f6' }}>
                                        <button
                                            type="button"
                                            onClick={() => setSignupMethod('email')}
                                            style={{
                                                backgroundColor: signupMethod === 'email' ? '#3b82f6' : 'transparent',
                                                color: signupMethod === 'email' ? '#ffffff' : isDarkTheme ? '#d1d5db' : '#0f172a'
                                            }}
                                            className="flex-1 flex items-center justify-center gap-2 px-3 py-2 rounded text-xs sm:text-sm font-medium transition-colors duration-200"
                                        >
                                            <Mail className="w-4 h-4" /> Email
                                        </button>
                                        <button
                                            type="button"
                                            onClick={() => setSignupMethod('gmail')}
                                            style={{
                                                backgroundColor: signupMethod === 'gmail' ? '#3b82f6' : 'transparent',
                                                color: signupMethod === 'gmail' ? '#ffffff' : isDarkTheme ? '#d1d5db' : '#0f172a'
                                            }}
                                            className="flex-1 flex items-center justify-center gap-2 px-3 py-2 rounded text-xs sm:text-sm font-medium transition-colors duration-200"
                                        >
                                            Google
                                        </button>
                                        <button
                                            type="button"
                                            onClick={() => setSignupMethod('phone')}
                                            style={{
                                                backgroundColor: signupMethod === 'phone' ? '#3b82f6' : 'transparent',
                                                color: signupMethod === 'phone' ? '#ffffff' : isDarkTheme ? '#d1d5db' : '#0f172a'
                                            }}
                                            className="flex-1 flex items-center justify-center gap-2 px-3 py-2 rounded text-xs sm:text-sm font-medium transition-colors duration-200"
                                        >
                                            <Phone className="w-4 h-4" /> Phone
                                        </button>
                                    </div>

                                    <form onSubmit={handleSignup} className="space-y-4">
                                        <div className="flex gap-4">
                                            <div className="flex-1">
                                                <label className="block text-sm font-medium mb-2">{t('auth.firstName') || 'First Name'}</label>
                                                <input
                                                    type="text"
                                                    value={firstName}
                                                    onChange={(e) => setFirstName(e.target.value)}
                                                    placeholder={t('auth.firstNamePlaceholder') || 'John'}
                                                    className="w-full px-4 py-2.5 rounded-lg border text-sm sm:text-base"
                                                    style={{
                                                        backgroundColor: isDarkTheme ? '#0f172a' : '#ffffff',
                                                        borderColor: isDarkTheme ? '#334155' : '#d1d5db',
                                                        color: isDarkTheme ? '#ffffff' : '#0f172a'
                                                    }}
                                                />
                                            </div>
                                            <div className="flex-1">
                                                <label className="block text-sm font-medium mb-2">{t('auth.lastName') || 'Last Name'}</label>
                                                <input
                                                    type="text"
                                                    value={lastName}
                                                    onChange={(e) => setLastName(e.target.value)}
                                                    placeholder={t('auth.lastNamePlaceholder') || 'Doe'}
                                                    className="w-full px-4 py-2.5 rounded-lg border text-sm sm:text-base"
                                                    style={{
                                                        backgroundColor: isDarkTheme ? '#0f172a' : '#ffffff',
                                                        borderColor: isDarkTheme ? '#334155' : '#d1d5db',
                                                        color: isDarkTheme ? '#ffffff' : '#0f172a'
                                                    }}
                                                />
                                            </div>
                                        </div>

                                        {signupMethod === 'email' && (
                                            <>
                                                <div>
                                                    <label className="block text-sm font-medium mb-2">{t('auth.email') || 'Email'}</label>
                                                    <div className="relative">
                                                        <Mail className="absolute left-3 top-3 w-5 h-5" style={{ color: '#9ca3af' }} />
                                                        <input
                                                            type="email"
                                                            value={email}
                                                            onChange={(e) => setEmail(e.target.value)}
                                                            placeholder={t('auth.emailPlaceholder') || 'your@email.com'}
                                                            className="w-full pl-10 pr-4 py-2.5 rounded-lg border text-sm sm:text-base"
                                                            style={{
                                                                backgroundColor: isDarkTheme ? '#0f172a' : '#ffffff',
                                                                borderColor: isDarkTheme ? '#334155' : '#d1d5db',
                                                                color: isDarkTheme ? '#ffffff' : '#0f172a'
                                                            }}
                                                        />
                                                    </div>
                                                </div>
                                                <div>
                                                    <label className="block text-sm font-medium mb-2">{t('auth.password') || 'Password'}</label>
                                                    <div className="relative">
                                                        <Lock className="absolute left-3 top-3 w-5 h-5" style={{ color: '#9ca3af' }} />
                                                        <input
                                                            type="password"
                                                            value={password}
                                                            onChange={(e) => setPassword(e.target.value)}
                                                            placeholder="••••••••"
                                                            className="w-full pl-10 pr-4 py-2.5 rounded-lg border text-sm sm:text-base"
                                                            style={{
                                                                backgroundColor: isDarkTheme ? '#0f172a' : '#ffffff',
                                                                borderColor: isDarkTheme ? '#334155' : '#d1d5db',
                                                                color: isDarkTheme ? '#ffffff' : '#0f172a'
                                                            }}
                                                        />
                                                    </div>
                                                </div>
                                            </>
                                        )}

                                        {signupMethod === 'gmail' && (
                                            <button
                                                type="button"
                                                className="w-full px-4 py-2.5 rounded-lg border font-medium text-sm sm:text-base transition-all duration-200 hover:shadow-md"
                                                style={{
                                                    borderColor: '#db4437',
                                                    color: '#db4437',
                                                    backgroundColor: isDarkTheme ? '#0f172a' : '#ffffff'
                                                }}
                                            >
                                                {t('auth.signupWithGoogle') || 'Sign up with Google'}
                                            </button>
                                        )}

                                        {signupMethod === 'phone' && (
                                            <div>
                                                <label className="block text-sm font-medium mb-2">{t('auth.phone') || 'Phone Number'}</label>
                                                <div className="relative">
                                                    <Phone className="absolute left-3 top-3 w-5 h-5" style={{ color: '#9ca3af' }} />
                                                    <input
                                                        type="tel"
                                                        value={phone}
                                                        onChange={(e) => setPhone(e.target.value)}
                                                        placeholder={t('auth.phonePlaceholder') || '+1 (555) 000-0000'}
                                                        className="w-full pl-10 pr-4 py-2.5 rounded-lg border text-sm sm:text-base"
                                                        style={{
                                                            backgroundColor: isDarkTheme ? '#0f172a' : '#ffffff',
                                                            borderColor: isDarkTheme ? '#334155' : '#d1d5db',
                                                            color: isDarkTheme ? '#ffffff' : '#0f172a'
                                                        }}
                                                    />
                                                </div>
                                            </div>
                                        )}

                                        <button
                                            type="submit"
                                            className="w-full px-4 py-2.5 rounded-lg font-semibold text-white text-sm sm:text-base transition-all duration-200 hover:shadow-lg hover:scale-105"
                                            style={{ backgroundColor: '#3b82f6' }}
                                        >
                                            {t('auth.signup') || 'Sign Up'}
                                        </button>
                                    </form>
                                </div>
                            )}
                        </div>
                    </div>
                </div>

                {/* Mobile Features Section */}
                <div className="lg:hidden mt-12">
                    <h3 className="text-2xl font-bold mb-6 text-center">{t('features.systemFeatures') || 'System Features'}</h3>
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 max-w-2xl mx-auto">
                        {features.map((feature, idx) => {
                            const Icon = feature.icon
                            return (
                                <div
                                    key={idx}
                                    className="p-4 rounded-lg transition-all duration-300 hover:scale-105 cursor-pointer"
                                    style={{
                                        backgroundColor: isDarkTheme ? '#1e293b' : '#f3f4f6',
                                        borderLeft: '4px solid #3b82f6'
                                    }}
                                >
                                    <div className="flex gap-3 mb-2">
                                        <div
                                            className="flex-shrink-0 w-10 h-10 rounded-lg flex items-center justify-center"
                                            style={{
                                                backgroundColor: '#3b82f6',
                                                boxShadow: '0 4px 12px rgba(59, 130, 246, 0.2)'
                                            }}
                                        >
                                            <Icon className="w-5 h-5 text-white" />
                                        </div>
                                    </div>
                                    <h4 className="font-semibold text-sm mb-1">{feature.title}</h4>
                                    <p className="text-xs" style={{ color: isDarkTheme ? '#9ca3af' : '#6b7280' }}>
                                        {feature.description}
                                    </p>
                                </div>
                            )
                        })}
                    </div>
                </div>
            </div>

            {/* Floating AI Chat Button */}
            <AIChat />
        </div>
    )
}

export default LoginPage

