import { useState, useEffect, useRef } from 'react'
import Peer from 'simple-peer/simplepeer.min.js'
import { Phone, PhoneOff, Mic, MicOff, Video, VideoOff } from 'lucide-react'

/**
 * @file CallModal.jsx
 * @description WebRTC Video/Audio Call Component. Handles signal exchange, media streams, and UI controls.
 * @module components/chat/CallModal
 * @param {boolean} isOpen - Whether modal is open.
 * @param {Function} onClose - Close handler.
 * @param {Object} socket - Socket.IO instance.
 * @param {Object} user - Current user.
 * @param {Object} targetUser - User to call.
 * @param {boolean} isIncoming - Is this an incoming call?
 * @param {Object} incomingCallSignal - RTC signal data for incoming calls.
 * @param {boolean} isVideoCall - Is video enabled?
 */
const CallModal = ({ 
    isOpen, 
    onClose, 
    socket, 
    user, 
    targetUser, 
    isIncoming, 
    incomingCallSignal, 
    isVideoCall 
}) => {
    const [stream, setStream] = useState(null)
    const [callAccepted, setCallAccepted] = useState(false)
    const [callEnded, setCallEnded] = useState(false)
    const [isMuted, setIsMuted] = useState(false)
    const [isVideoEnabled, setIsVideoEnabled] = useState(isVideoCall)
    
    const myVideo = useRef()
    const userVideo = useRef()
    const connectionRef = useRef()

    useEffect(() => {
        if (isOpen) {
            navigator.mediaDevices.getUserMedia({ video: isVideoCall, audio: true })
                .then((currentStream) => {
                    setStream(currentStream)
                    if (myVideo.current) {
                        myVideo.current.srcObject = currentStream
                    }

                    if (isIncoming) {
                        // Wait for manual answer
                    } else {
                        // Initiator
                        const peer = new Peer({
                            initiator: true,
                            trickle: false,
                            stream: currentStream || undefined
                        })

                        peer.on('signal', (data) => {
                            socket.emit('call_user', {
                                userToCall: targetUser._id,
                                signalData: data,
                                from: (user?._id || user?.id),
                                name: `${user.fullName?.firstName} ${user.fullName?.lastName}`,
                                isVideo: isVideoCall
                            })
                        })

                        peer.on('error', (err) => {
                            console.error('Peer connection error (initiator):', err)
                            // Optional: Show user feedback
                        })

                        peer.on('stream', (currentStream) => {
                            if (userVideo.current) {
                                userVideo.current.srcObject = currentStream
                            }
                        })

                        socket.on('call_accepted', (signal) => {
                            setCallAccepted(true)
                            peer.signal(signal)
                        })

                        connectionRef.current = peer
                    }
                })
        }

        return () => {
            // Cleanup on unmount or close
            connectionRef.current?.destroy()
            if (stream) {
                stream.getTracks().forEach(track => track.stop())
            }
            socket.off('call_accepted')
        }
    }, [isOpen])

    const answerCall = () => {
        setCallAccepted(true)
        const peer = new Peer({
            initiator: false,
            trickle: false,
            stream: stream || undefined
        })

        peer.on('signal', (data) => {
            socket.emit('answer_call', { signal: data, to: targetUser._id })
        })

        peer.on('error', (err) => {
            console.error('Peer connection error (receiver):', err)
        })

        peer.on('stream', (currentStream) => {
            if (userVideo.current) {
                userVideo.current.srcObject = currentStream
            }
        })

        peer.signal(incomingCallSignal)
        connectionRef.current = peer
    }

    const leaveCall = () => {
        setCallEnded(true)
        socket.emit('end_call', { to: targetUser._id })
        connectionRef.current?.destroy()
        onClose()
    }

    const toggleMute = () => {
        if (stream) {
            stream.getAudioTracks()[0].enabled = !stream.getAudioTracks()[0].enabled
            setIsMuted(!isMuted)
        }
    }

    const toggleVideo = () => {
        if (stream && isVideoCall) {
            stream.getVideoTracks()[0].enabled = !stream.getVideoTracks()[0].enabled
            setIsVideoEnabled(!isVideoEnabled)
        }
    }

    // Close on Escape
    useEffect(() => {
        const handleKeyDown = (e) => {
            if (e.key === 'Escape' && isOpen) {
                leaveCall();
            }
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [isOpen]);

    if (!isOpen) return null

    return (
        <div className="fixed inset-0 z-[100] bg-black/90 flex flex-col items-center justify-center">
            <div className="relative w-full max-w-4xl h-full max-h-[80vh] flex flex-col items-center justify-center gap-4 p-4">
                
                {/* Video Area */}
                <div className="flex-1 w-full flex flex-col md:flex-row gap-4 items-center justify-center relative">
                    {callAccepted && !callEnded ? (
                        <video playsInline ref={userVideo} autoPlay className="w-full h-full object-cover rounded-2xl bg-gray-800" />
                    ) : (
                        <div className="w-full h-full flex items-center justify-center bg-gray-800 rounded-2xl">
                            <div className="text-center">
                                <div className="w-24 h-24 rounded-full bg-blue-500 flex items-center justify-center text-4xl text-white font-bold mx-auto mb-4">
                                    {targetUser?.fullName?.firstName?.charAt(0)}
                                </div>
                                <h3 className="text-xl text-white font-bold">
                                    {isIncoming && !callAccepted ? 'Incoming call from...' : 'Calling...'}
                                </h3>
                                <p className="text-gray-400 text-lg">
                                    {targetUser?.fullName?.firstName} {targetUser?.fullName?.lastName}
                                </p>
                            </div>
                        </div>
                    )}
                    
                    {/* My Video (PiP) */}
                    {stream && isVideoCall && (
                        <div className="absolute right-4 bottom-24 md:bottom-4 w-32 h-48 md:w-48 md:h-72 bg-black rounded-xl overflow-hidden border-2 border-white/20 shadow-xl">
                            <video playsInline muted ref={myVideo} autoPlay className="w-full h-full object-cover" />
                        </div>
                    )}
                </div>
                
                {/* Controls */}
                <div className="flex items-center gap-6 pb-8">
                    {/* Only show answer button if incoming and not accepted */}
                    {isIncoming && !callAccepted ? (
                        <button 
                            onClick={answerCall} 
                            className="p-4 rounded-full bg-green-500 hover:bg-green-600 text-white shadow-lg transform hover:scale-110 transition-all"
                        >
                            <Phone className="w-8 h-8" />
                        </button>
                    ) : null}

                    {/* Mute Toggle */}
                    <button 
                        onClick={toggleMute} 
                        className={`p-4 rounded-full ${isMuted ? 'bg-red-500 text-white' : 'bg-gray-700 text-white'} hover:opacity-90 transition-all`}
                    >
                        {isMuted ? <MicOff className="w-6 h-6" /> : <Mic className="w-6 h-6" />}
                    </button>

                    {/* Video Toggle (Only if video call) */}
                    {isVideoCall && (
                        <button 
                            onClick={toggleVideo} 
                            className={`p-4 rounded-full ${!isVideoEnabled ? 'bg-red-500 text-white' : 'bg-gray-700 text-white'} hover:opacity-90 transition-all`}
                        >
                            {!isVideoEnabled ? <VideoOff className="w-6 h-6" /> : <Video className="w-6 h-6" />}
                        </button>
                    )}
                    
                    {/* End Call */}
                    <button 
                        onClick={leaveCall} 
                        className="p-4 rounded-full bg-red-600 hover:bg-red-700 text-white shadow-lg transform hover:scale-110 transition-all"
                    >
                        <PhoneOff className="w-8 h-8" />
                    </button>
                </div>
            </div>
        </div>
    )
}

export default CallModal
