import { useTranslation } from 'react-i18next'
import { useThemeStore } from '../store/themeStore'
import { useAuthStore } from '../store/authStore'
import { Calendar, MessageSquare, Shield, Activity, TrendingUp, CheckCircle, Clock } from 'lucide-react'

function DashboardPage() {
    const { t } = useTranslation()
    const theme = useThemeStore((state) => state.theme)
    const { user, role } = useAuthStore()

    const isDarkTheme = theme === 'dark' || (theme === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches)

    // Helper for glassmorphism styles
    const cardStyle = {
        backgroundColor: isDarkTheme ? 'rgba(30, 41, 59, 0.4)' : 'rgba(255, 255, 255, 0.6)',
        backdropFilter: 'blur(12px)',
        border: `1px solid ${isDarkTheme ? 'rgba(255, 255, 255, 0.1)' : 'rgba(255, 255, 255, 0.4)'}`,
        boxShadow: isDarkTheme ? '0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06)' : '0 10px 30px -5px rgba(0, 0, 0, 0.05)',
    }

    return (
        <div className="p-4 sm:p-6 lg:p-8 space-y-8 animate-in fade-in duration-500">
            {/* Header Section */}
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <div>
                    <h1 className="text-3xl sm:text-4xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-600 to-cyan-500 mb-2">
                        {t('dashboard.welcome') || 'Welcome back'}, {user?.fullName?.firstName ? `${user.fullName.firstName} ${user.fullName.lastName}` : user?.fullName}!
                    </h1>
                    <p className="text-sm font-medium flex items-center gap-2" style={{ color: isDarkTheme ? '#94a3b8' : '#64748b' }}>
                        <span className="capitalize px-2 py-1 rounded-md bg-opacity-20 text-blue-500 bg-blue-500">
                            {role}
                        </span>
                        <span>•</span>
                        <span>{new Date().toLocaleDateString(undefined, { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</span>
                    </p>
                </div>
            </div>

            {/* Stats Grid */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
                {[
                    { title: t('dashboard.upcomingAppointments') || 'Appointments', value: '3', sub: t('dashboard.nextToday') || '1 Today', icon: Calendar, color: 'blue' },
                    { title: t('dashboard.unreadMessages') || 'Messages', value: '5', sub: t('dashboard.new') || '2 New', icon: MessageSquare, color: 'green' },
                    { title: t('dashboard.accountStatus') || 'Plan', value: 'Basic', sub: t('dashboard.upgrade') || 'Upgrade', icon: Shield, color: 'purple', isText: true },
                    { title: t('health.heartRate') || 'Heart Rate', value: '72', sub: 'bpm', icon: Activity, color: 'rose' },
                ].map((stat, index) => (
                    <div
                        key={index}
                        className="rounded-2xl p-6 transition-all duration-300 hover:scale-[1.02] hover:shadow-lg relative overflow-hidden group"
                        style={cardStyle}
                    >
                        <div className={`absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity`}>
                            <stat.icon size={64} className={`text-${stat.color}-500`} />
                        </div>
                        <div className="relative z-10">
                            <p className="text-sm font-medium mb-1" style={{ color: isDarkTheme ? '#94a3b8' : '#64748b' }}>{stat.title}</p>
                            <h3 className="text-3xl font-bold" style={{ color: isDarkTheme ? '#f1f5f9' : '#1e293b' }}>{stat.value}</h3>
                            <p className={`text-xs font-semibold mt-2 text-${stat.color}-500`}>
                                {stat.sub}
                            </p>
                        </div>
                    </div>
                ))}
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                {/* Recent Activity */}
                <div className="lg:col-span-2 rounded-2xl p-6" style={cardStyle}>
                    <div className="flex items-center justify-between mb-6">
                        <h2 className="text-xl font-bold flex items-center gap-2" style={{ color: isDarkTheme ? '#f1f5f9' : '#1e293b' }}>
                            <TrendingUp className="w-5 h-5 text-cyan-500" />
                            {t('dashboard.recentActivity') || 'Recent Activity'}
                        </h2>
                        <button className="text-sm font-semibold text-blue-500 hover:text-blue-600 transition-colors">
                            {t('table.viewDetails') || 'View All'}
                        </button>
                    </div>
                    
                    <div className="space-y-4">
                        {[
                            { title: 'Appointment with Dr. Sarah', time: '2 hours ago', type: 'appointment', status: 'completed' },
                            { title: 'New Health Log Added', time: '5 hours ago', type: 'health', status: 'success' },
                            { title: 'Prescription Refilled', time: 'Yesterday', type: 'pharmacy', status: 'processing' },
                            { title: 'Profile Updated', time: '2 days ago', type: 'settings', status: 'completed' },
                        ].map((item, idx) => (
                            <div 
                                key={idx} 
                                className="flex items-center p-4 rounded-xl transition-colors duration-200 hover:bg-black/5 dark:hover:bg-white/5"
                            >
                                <div className={`w-10 h-10 rounded-full flex items-center justify-center mr-4 ${
                                    item.status === 'completed' ? 'bg-green-100 text-green-600 dark:bg-green-900/30 dark:text-green-400' :
                                    item.status === 'processing' ? 'bg-amber-100 text-amber-600 dark:bg-amber-900/30 dark:text-amber-400' :
                                    'bg-blue-100 text-blue-600 dark:bg-blue-900/30 dark:text-blue-400'
                                }`}>
                                    {item.status === 'completed' || item.status === 'success' ? <CheckCircle size={18} /> : 
                                     item.status === 'processing' ? <Clock size={18} /> : <Activity size={18} />}
                                </div>
                                <div className="flex-1">
                                    <h4 className="font-semibold text-sm sm:text-base" style={{ color: isDarkTheme ? '#e2e8f0' : '#334155' }}>{item.title}</h4>
                                    <p className="text-xs" style={{ color: isDarkTheme ? '#94a3b8' : '#64748b' }}>{item.time}</p>
                                </div>
                                <span className={`text-xs px-3 py-1 rounded-full font-medium ${
                                    item.status === 'completed' ? 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-300' :
                                    item.status === 'processing' ? 'bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-300' :
                                    'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-300'
                                }`}>
                                    {item.status}
                                </span>
                            </div>
                        ))}
                    </div>
                </div>

                {/* Quick Actions / Today's Schedule */}
                <div className="space-y-6">
                     <div className="rounded-2xl p-6 h-full" style={{
                         ...cardStyle,
                         background: isDarkTheme ? 'linear-gradient(145deg, rgba(30,58,138,0.2), rgba(15,23,42,0.6))' : 'linear-gradient(145deg, rgba(239,246,255,0.8), rgba(255,255,255,0.9))'
                     }}>
                        <h2 className="text-xl font-bold mb-6 flex items-center gap-2" style={{ color: isDarkTheme ? '#f1f5f9' : '#1e293b' }}>
                            <Calendar className="w-5 h-5 text-blue-500" />
                            {t('dashboard.todaySchedule') || "Today's Schedule"}
                        </h2>
                        
                        <div className="relative pl-6 border-l-2 border-blue-200 dark:border-blue-900 space-y-8">
                            {[
                                { time: '09:00 AM', title: 'Blood Test', doctor: 'Dr. Mike', active: false },
                                { time: '02:00 PM', title: 'Consultation', doctor: 'Dr. Sarah', active: true },
                                { time: '04:30 PM', title: 'Physiotherapy', doctor: 'Therapist John', active: false },
                            ].map((event, idx) => (
                                <div key={idx} className="relative">
                                    <div className={`absolute -left-[29px] top-1 w-4 h-4 rounded-full border-2 ${
                                        event.active ? 'bg-blue-500 border-blue-500 ring-4 ring-blue-500/20' : 
                                        'bg-white dark:bg-slate-900 border-gray-300 dark:border-gray-600'
                                    }`}></div>
                                    <div className={`transition-all duration-300 ${event.active ? 'opacity-100' : 'opacity-70 group-hover:opacity-100'}`}>
                                        <p className="text-xs font-bold text-blue-500 mb-1">{event.time}</p>
                                        <h4 className="font-semibold text-sm">{event.title}</h4>
                                        <p className="text-xs text-gray-500">{event.doctor}</p>
                                    </div>
                                </div>
                            ))}
                        </div>
                        
                        <button className="w-full mt-8 py-3 rounded-xl bg-blue-500 hover:bg-blue-600 text-white font-semibold text-sm transition-all shadow-lg hover:shadow-blue-500/30">
                            {t('ui.bookAppointment') || 'Book New Appointment'}
                        </button>
                    </div>
                </div>
            </div>
        </div>
    )
}

export default DashboardPage
