import axiosClient from './axiosClient';

/**
 * @file messageApi.js
 * @description API endpoints for messaging and file uploads.
 * @module api/messageApi
 */
const messageApi = {
    // Get all conversations
    getConversations: () => axiosClient.get('/messages/conversations'),

    // Get or create a conversation
    getOrCreateConversation: (userId, type, name, participants) => axiosClient.post('/messages/conversations', { participantId: userId, type, name, participants }),

    // Update conversation
    updateConversation: (id, data) => axiosClient.put(`/messages/conversations/${id}`, data),

    // Get messages    // Get conversation messages
    getMessages: (conversationId, params) => axiosClient.get(`/messages/${conversationId}`, { params }),

    // Send message
    sendMessage: (conversationId, data) => axiosClient.post(`/messages/${conversationId}`, data),

    // Mark as read
    markAsRead: (conversationId) => axiosClient.put(`/messages/${conversationId}/read`),

    // Delete message
    deleteMessage: (messageId, forEveryone) => axiosClient.delete(`/messages/message/${messageId}`, { data: { forEveryone } }),

    // Upload file
    uploadFile: (file, onProgress) => {
        const formData = new FormData();
        formData.append('file', file);

        return axiosClient.post('/messages/upload', formData, {
            headers: { 'Content-Type': 'multipart/form-data' },
            onUploadProgress: (progressEvent) => {
                if (onProgress) {
                    const percentCompleted = Math.round((progressEvent.loaded * 100) / progressEvent.total);
                    onProgress(percentCompleted);
                }
            }
        });
    }
};

export default messageApi;
