import { useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { useTranslation } from 'react-i18next'
import { useThemeStore } from '../store/themeStore'
import { Mail, ArrowLeft } from 'lucide-react'

function PasswordResetPage() {
    const navigate = useNavigate()
    const { t, i18n } = useTranslation()
    const theme = useThemeStore((state) => state.theme)
    const [email, setEmail] = useState('')
    const [submitted, setSubmitted] = useState(false)

    const isDarkTheme = theme === 'dark' || (theme === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches)

    const handleSubmit = (e) => {
        e.preventDefault()
        if (!email) return
        setSubmitted(true)
        // In real app, send reset email here
    }

    return (
        <div
            className="min-h-screen flex items-center justify-center px-4 sm:px-6 lg:px-8 transition-colors duration-200"
            style={{
                backgroundColor: isDarkTheme ? '#0f172a' : '#ffffff',
                color: isDarkTheme ? '#ffffff' : '#0f172a'
            }}
        >
            <div className="w-full max-w-md">
                {/* Back Button */}
                <button
                    onClick={() => navigate('/login')}
                    className="flex items-center gap-2 text-sm sm:text-base mb-6 transition-colors duration-200"
                    style={{ color: '#3b82f6' }}
                >
                    <ArrowLeft className="w-4 h-4" />
                    {t('backToLogin') || 'Back to Login'}
                </button>

                {/* Header */}
                <div className="text-center mb-8">
                    <h1 className="text-2xl sm:text-3xl md:text-4xl font-bold mb-2">{t('resetPassword') || 'Reset Password'}</h1>
                    <p className="text-sm sm:text-base" style={{ color: isDarkTheme ? '#9ca3af' : '#6b7280' }}>
                        {t('resetPasswordDesc') || 'Enter your email to receive a password reset link'}
                    </p>
                </div>

                {/* Form Card */}
                <div
                    className="p-6 sm:p-8 rounded-lg shadow-lg"
                    style={{
                        backgroundColor: isDarkTheme ? '#1e293b' : '#f9fafb',
                        border: `1px solid ${isDarkTheme ? '#334155' : '#e5e7eb'}`
                    }}
                >
                    {!submitted ? (
                        <form onSubmit={handleSubmit} className="space-y-4">
                            <div>
                                <label className="block text-sm font-medium mb-2">{t('email') || 'Email Address'}</label>
                                <div className="relative">
                                    <Mail className="absolute left-3 top-3 w-5 h-5" style={{ color: '#9ca3af' }} />
                                    <input
                                        type="email"
                                        value={email}
                                        onChange={(e) => setEmail(e.target.value)}
                                        placeholder={t('emailPlaceholder') || 'your@email.com'}
                                        className="w-full pl-10 pr-4 py-2 rounded-lg border text-sm sm:text-base"
                                        style={{
                                            backgroundColor: isDarkTheme ? '#0f172a' : '#ffffff',
                                            borderColor: isDarkTheme ? '#334155' : '#d1d5db',
                                            color: isDarkTheme ? '#ffffff' : '#0f172a'
                                        }}
                                        required
                                    />
                                </div>
                            </div>

                            <button
                                type="submit"
                                className="w-full px-4 py-2 rounded-lg font-medium text-white text-sm sm:text-base transition-colors duration-200 hover:bg-blue-600"
                                style={{ backgroundColor: '#3b82f6' }}
                            >
                                {t('sendResetLink') || 'Send Reset Link'}
                            </button>
                        </form>
                    ) : (
                        <div className="text-center space-y-4">
                            <div
                                className="w-12 h-12 mx-auto rounded-full flex items-center justify-center"
                                style={{ backgroundColor: '#d1fae5' }}
                            >
                                <span style={{ color: '#059669', fontSize: '24px' }}>✓</span>
                            </div>
                            <h2 className="text-lg sm:text-xl font-semibold">{t('emailSent') || 'Email Sent!'}</h2>
                            <p className="text-sm" style={{ color: isDarkTheme ? '#9ca3af' : '#6b7280' }}>
                                {t('checkEmail') || 'Check your email for a link to reset your password. If it doesn\'t appear within a few minutes, check your spam folder.'}
                            </p>
                            <button
                                onClick={() => navigate('/login')}
                                className="w-full px-4 py-2 rounded-lg font-medium text-white text-sm sm:text-base transition-colors duration-200 hover:bg-blue-600 mt-6"
                                style={{ backgroundColor: '#3b82f6' }}
                            >
                                {t('backToLogin') || 'Back to Login'}
                            </button>
                        </div>
                    )}
                </div>
            </div>
        </div>
    )
}

export default PasswordResetPage
