import axiosClient from './axiosClient';

/**
 * @file userApi.js
 * @description API endpoints for user data.
 * @module api/userApi
 */
const userApi = {
    // Search users
    searchUsers: (query) => axiosClient.get('/users/search', { params: { q: query } }),

    // Get user by ID
    getUserById: (id) => axiosClient.get(`/users/${id}`)
};

export default userApi;
