import { create } from 'zustand'
import { persist } from 'zustand/middleware'

const applyTheme = (theme) => {
    const html = document.documentElement
    const root = document.getElementById('root')

    // Remove all theme classes first
    html.classList.remove('dark', 'light')

    if (theme === 'system') {
        const isDark = window.matchMedia('(prefers-color-scheme: dark)').matches
        if (isDark) {
            html.classList.add('dark')
        }
    } else if (theme === 'dark') {
        html.classList.add('dark')
    }

    console.log('Theme applied:', theme, 'Dark class present:', html.classList.contains('dark'))
}

// Initialize theme immediately on load before React renders
const initializeThemeOnLoad = () => {
    const stored = localStorage.getItem('theme-store')
    if (stored) {
        try {
            const state = JSON.parse(stored).state
            if (state && state.theme) {
                applyTheme(state.theme)
                return
            }
        } catch (e) {
            console.error('Failed to parse stored theme:', e)
        }
    }
    applyTheme('system')
}

// Only initialize if we have stored theme data
const storedData = localStorage.getItem('theme-store')
if (storedData) {
    try {
        const state = JSON.parse(storedData).state
        if (state && state.theme) {
            applyTheme(state.theme)
        }
    } catch (e) {
        console.error('Failed to initialize theme:', e)
    }
}

export const useThemeStore = create(
    persist(
        (set, get) => ({
            theme: 'system',
            systemThemeChanged: 0, // Force re-render when system theme changes

            setTheme: (theme) => {
                console.log('setTheme called with:', theme)
                set({ theme })
                applyTheme(theme)
            },

            initTheme: () => {
                const stored = localStorage.getItem('theme-store')
                if (stored) {
                    try {
                        const state = JSON.parse(stored).state
                        if (state && state.theme) {
                            applyTheme(state.theme)
                            return
                        }
                    } catch (e) {
                        console.error('Failed to parse stored theme:', e)
                    }
                }
                applyTheme('system')
            },

            triggerSystemThemeUpdate: () => {
                set((state) => ({ systemThemeChanged: state.systemThemeChanged + 1 }))
            },
        }),
        {
            name: 'theme-store',
        }
    )
)

// Listen for system theme changes
if (typeof window !== 'undefined') {
    window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', () => {
        const store = useThemeStore.getState()
        if (store.theme === 'system') {
            applyTheme('system')
            // Force React to re-render by triggering state update
            store.triggerSystemThemeUpdate()
        }
    })
}
