import { useTranslation } from 'react-i18next'
import { useThemeStore } from '../store/themeStore'
import { Phone, Mail, Calendar } from 'lucide-react'

function PatientsPage() {
    const { t } = useTranslation()
    const theme = useThemeStore((state) => state.theme)

    const isDarkTheme = theme === 'dark' || (theme === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches)

    const patients = [
        { id: 1, name: 'John Doe', email: 'john@example.com', phone: '+1234567890', lastVisit: '2025-01-01' },
        { id: 2, name: 'Jane Smith', email: 'jane@example.com', phone: '+1234567891', lastVisit: '2024-12-28' },
        { id: 3, name: 'Bob Johnson', email: 'bob@example.com', phone: '+1234567892', lastVisit: '2024-12-25' },
    ]

    return (
        <div className="p-4 sm:p-6 lg:p-8">
            <div className="mb-6 flex justify-between items-center flex-wrap gap-4">
                <h1 className="text-2xl sm:text-3xl font-bold">{t('patients') || 'Patients'}</h1>
                <input
                    type="text"
                    placeholder={t('searchPatients') || 'Search patients...'}
                    className="px-4 py-2 rounded-lg border text-sm"
                    style={{
                        backgroundColor: isDarkTheme ? '#0f172a' : '#ffffff',
                        borderColor: isDarkTheme ? '#334155' : '#e5e7eb',
                        color: isDarkTheme ? '#ffffff' : '#0f172a'
                    }}
                />
            </div>

            <div
                className="rounded-lg border overflow-hidden"
                style={{
                    backgroundColor: isDarkTheme ? '#1e293b' : '#ffffff',
                    borderColor: isDarkTheme ? '#334155' : '#e5e7eb'
                }}
            >
                <div className="overflow-x-auto">
                    <table className="w-full text-sm">
                        <thead style={{ backgroundColor: isDarkTheme ? '#0f172a' : '#f9fafb' }}>
                            <tr>
                                <th className="px-4 py-3 text-left font-semibold">{t('name') || 'Name'}</th>
                                <th className="px-4 py-3 text-left font-semibold">{t('email') || 'Email'}</th>
                                <th className="px-4 py-3 text-left font-semibold">{t('phone') || 'Phone'}</th>
                                <th className="px-4 py-3 text-left font-semibold">{t('lastVisit') || 'Last Visit'}</th>
                                <th className="px-4 py-3 text-left font-semibold">{t('actions') || 'Actions'}</th>
                            </tr>
                        </thead>
                        <tbody>
                            {patients.map((patient) => (
                                <tr key={patient.id} style={{ borderTop: `1px solid ${isDarkTheme ? '#334155' : '#e5e7eb'}` }}>
                                    <td className="px-4 py-3 font-medium">{patient.name}</td>
                                    <td className="px-4 py-3">
                                        <a href={`mailto:${patient.email}`} className="text-blue-500 hover:underline flex items-center gap-1">
                                            <Mail className="w-4 h-4" /> {patient.email}
                                        </a>
                                    </td>
                                    <td className="px-4 py-3">
                                        <a href={`tel:${patient.phone}`} className="text-blue-500 hover:underline flex items-center gap-1">
                                            <Phone className="w-4 h-4" /> {patient.phone}
                                        </a>
                                    </td>
                                    <td className="px-4 py-3 flex items-center gap-1">
                                        <Calendar className="w-4 h-4" /> {patient.lastVisit}
                                    </td>
                                    <td className="px-4 py-3">
                                        <button className="px-3 py-1 rounded bg-blue-500 text-white text-xs hover:bg-blue-600">
                                            {t('viewDetails') || 'View'}
                                        </button>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    )
}

export default PatientsPage
