import { useState } from 'react'
import { useTranslation } from 'react-i18next'
import { useThemeStore } from '../../store/themeStore'
import { Bot, X } from 'lucide-react'

const AIChat = ({ isMobile, isRtl }) => {
    const { t } = useTranslation()
    const theme = useThemeStore((state) => state.theme)
    const [chatOpen, setChatOpen] = useState(false)
    const isDarkTheme = theme === 'dark' || (theme === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches)

    return (
        <>
            {/* Floating AI Chat Window */}
            {chatOpen && (
                <div
                    className="fixed z-50 flex flex-col rounded-2xl shadow-2xl overflow-hidden transition-all duration-300 ease-out"
                    style={{
                        backgroundColor: isDarkTheme ? '#1e293b' : '#ffffff',
                        border: `1px solid ${isDarkTheme ? '#334155' : '#e5e7eb'}`,
                        width: isMobile ? 'calc(100% - 2rem)' : '380px',
                        height: isMobile ? 'calc(100% - 6rem)' : '500px',
                        [isRtl ? 'left' : 'right']: isMobile ? '1rem' : '2rem',
                        [isRtl ? 'right' : 'left']: 'auto',
                        bottom: isMobile ? '5rem' : '2rem',
                        boxShadow: `0 12px 40px ${isDarkTheme ? 'rgba(0, 0, 0, 0.4)' : 'rgba(0, 0, 0, 0.1)'}`
                    }}
                >
                    {/* Chat Header */}
                    <div className="h-14 px-4 flex items-center justify-between flex-shrink-0 bg-gradient-to-r from-blue-500 to-cyan-500">
                        <div className="flex items-center gap-2">
                            <Bot className="w-5 h-5 text-white" />
                            <h3 className="font-semibold text-white text-sm">{t('chat.aiAssistant') || 'AI Assistant'}</h3>
                        </div>
                        <button
                            onClick={() => setChatOpen(false)}
                            className="p-1 rounded-lg hover:bg-white hover:bg-opacity-20 transition-colors duration-200"
                            title="Close chat"
                        >
                            <X className="w-5 h-5 text-white" />
                        </button>
                    </div>

                    {/* Chat Messages */}
                    <div className="flex-1 overflow-y-auto p-4 space-y-3">
                        <div
                            className="p-3 rounded-lg max-w-xs text-sm shadow-sm"
                            style={{
                                backgroundColor: isDarkTheme ? 'rgba(14, 165, 233, 0.15)' : '#e0f2fe',
                                color: isDarkTheme ? '#e0f2fe' : '#0369a1',
                                borderLeft: '3px solid #0ea5e9'
                            }}
                        >
                            <p className="font-medium">{t('chat.aiGreeting') || 'Hello! How can I help you today?'}</p>
                        </div>
                    </div>

                    {/* Chat Input */}
                    <div
                        className="p-3 border-t flex-shrink-0"
                        style={{ borderColor: isDarkTheme ? '#334155' : '#e5e7eb' }}
                    >
                        <div className="flex gap-2">
                            <input
                                type="text"
                                placeholder={t('chat.typeMessage') || 'Type a message...'}
                                className="flex-1 px-3 py-2 rounded-lg border text-sm transition-all duration-200 focus:ring-2 focus:ring-blue-500 focus:ring-opacity-30 focus:outline-none"
                                style={{
                                    backgroundColor: isDarkTheme ? '#0f172a' : '#f8fafc',
                                    borderColor: isDarkTheme ? '#334155' : '#cbd5e1',
                                    color: isDarkTheme ? '#ffffff' : '#0f172a'
                                }}
                            />
                            <button
                                className="px-3 py-2 rounded-lg text-white font-medium text-sm transition-all duration-200 hover:shadow-lg hover:scale-105 bg-gradient-to-r from-blue-500 to-cyan-500 hover:from-blue-600 hover:to-cyan-600"
                                title="Send message"
                            >
                                {t('chat.send') || 'Send'}
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Floating AI Chat Button */}
            {!chatOpen && (
                <button
                    onClick={() => setChatOpen(true)}
                    className="fixed bottom-6 flex items-center justify-center w-14 h-14 rounded-full shadow-lg transition-all duration-300 hover:scale-110 hover:shadow-xl z-40"
                    style={{
                        background: 'linear-gradient(135deg, #0ea5e9 0%, #06b6d4 100%)',
                        boxShadow: `0 8px 24px ${isDarkTheme ? 'rgba(14, 165, 233, 0.4)' : 'rgba(14, 165, 233, 0.3)'}`,
                        [isRtl ? 'left' : 'right']: isMobile ? '1rem' : '2rem',
                        [isRtl ? 'right' : 'left']: 'auto'
                    }}
                    title={t('chat.aiChat') || 'AI Chat Assistant'}
                >
                    <Bot className="w-6 h-6 text-white" />
                </button>
            )}
        </>
    )
}

export default AIChat
