import { useNavigate, useLocation } from 'react-router-dom'
import { useTranslation } from 'react-i18next'
import { useAuthStore } from '../../store/authStore'
import { useThemeStore } from '../../store/themeStore'
import { 
    LogOut, Home, MessageSquare, Calendar, Heart, 
    Users, Crown, Settings 
} from 'lucide-react'

const BottomBar = () => {
    const navigate = useNavigate()
    const location = useLocation()
    const { t } = useTranslation()
    const { role, logout, isPremium } = useAuthStore()
    const theme = useThemeStore((state) => state.theme)
    
    // Derived state
    const isDarkTheme = theme === 'dark' || (theme === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches)
    const isActive = (path) => location.pathname === path

    const getMenuItems = () => {
        const baseItems = [
            { id: 'dashboard', label: t('navigation.dashboard') || 'Dashboard', icon: Home, path: '/dashboard', roles: ['patient', 'doctor', 'receptionist'] },
            { id: 'messages', label: t('navigation.messages') || 'Messages', icon: MessageSquare, path: '/messages', roles: ['patient', 'doctor', 'receptionist'] },
            { id: 'appointments', label: t('navigation.appointments') || 'Appointments', icon: Calendar, path: '/appointments', roles: ['patient', 'doctor', 'receptionist'] },
        ]

        const roleSpecific = {
            patient: [
                { id: 'health_logs', label: t('navigation.healthLogs') || 'Health Logs', icon: Heart, path: '/health-logs', roles: ['patient'] },
            ],
            doctor: [
                { id: 'patients', label: t('navigation.patients') || 'Patients', icon: Users, path: '/patients', roles: ['doctor', 'receptionist'] },
            ],
            receptionist: [
                { id: 'patients', label: t('navigation.patients') || 'Patients', icon: Users, path: '/patients', roles: ['doctor', 'receptionist'] },
            ]
        }

        const allItems = [
            ...baseItems,
            ...(roleSpecific[role] || []),
            { id: 'premium', label: t('navigation.premium') || 'Premium', icon: Crown, path: '/premium', roles: ['patient', 'doctor', 'receptionist'], badge: !isPremium ? 'New' : null },
            { id: 'settings', label: t('navigation.settings') || 'Settings', icon: Settings, path: '/settings', roles: ['patient', 'doctor', 'receptionist'] },
        ]

        return allItems.filter(item => item.roles.includes(role))
    }

    const menuItems = getMenuItems()

    const handleLogout = () => {
        logout()
        navigate('/login')
    }

    return (
        <div
            className="h-16 px-2 sm:px-4 flex items-center border-t md:hidden fixed bottom-0 left-0 right-0 z-30 backdrop-blur-md overflow-x-auto scrollbar-hide no-scrollbar"
            style={{
                backgroundColor: isDarkTheme ? 'rgba(15, 23, 42, 0.98)' : 'rgba(255, 255, 255, 0.98)',
                borderColor: isDarkTheme ? '#1e293b' : '#e5e7eb'
            }}
        >
            <div className="flex items-center justify-around w-full min-w-max space-x-2">
                {menuItems.map((item) => (
                    <button
                        key={item.id}
                        onClick={() => navigate(item.path)}
                        className="flex flex-col items-center gap-1 p-2 rounded-lg flex-shrink-0 transition-all duration-200 hover:shadow-md active:scale-95"
                        style={{
                            color: isActive(item.path) ? '#0ea5e9' : isDarkTheme ? '#9ca3af' : '#6b7280',
                            minWidth: '64px'
                        }}
                        title={item.label}
                    >
                        <item.icon className={`w-5 h-5 sm:w-6 sm:h-6 ${isActive(item.path) ? 'animate-bounce-short' : ''}`} />
                        <span className="text-[10px] leading-3 font-medium whitespace-nowrap">{item.label}</span>
                    </button>
                ))}
                
                <button
                    onClick={handleLogout}
                    className="flex flex-col items-center gap-1 p-2 rounded-lg flex-shrink-0 transition-all duration-200 hover:shadow-md active:scale-95 text-red-500"
                    style={{
                        minWidth: '64px'
                    }}
                    title={t('navigation.logout') || 'Logout'}
                >
                    <LogOut className="w-5 h-5 sm:w-6 sm:h-6" />
                    <span className="text-[10px] leading-3 font-medium whitespace-nowrap">{t('navigation.logout') || 'Logout'}</span>
                </button>
            </div>
            
            {/* CSS to hide scrollbar but allow functionality */}
            <style>{`
                .no-scrollbar::-webkit-scrollbar {
                    display: none;
                }
                .no-scrollbar {
                    -ms-overflow-style: none;
                    scrollbar-width: none;
                }
            `}</style>
        </div>
    )
}

export default BottomBar
