import { useState } from 'react'
import { ZoomIn, Reply, MoreVertical, Trash2 } from 'lucide-react'
import { useAuthStore } from '../../store/authStore'
import { useTranslation } from 'react-i18next'

const MessageBubble = ({ message, onReply, onDelete, onImageClick, onReplyClick }) => {
    const { user } = useAuthStore()
    const { t } = useTranslation()
    const [contextMenu, setContextMenu] = useState(null)
    const isMe = message.sender?._id === (user?._id || user?.id)
    const serverUrl = import.meta.env.VITE_SOCKET_URL || 'http://localhost:5000'

    const getMediaUrl = (url) => {
        if (!url) return ''
        if (url.startsWith('http')) return url
        return `${serverUrl}${url}`
    }

    return (
        <div id={`message-${message._id}`} className={`flex flex-col ${isMe ? 'items-end' : 'items-start'} group relative`}>
            {message.replyTo && (
                <div 
                    className={`mb-1 text-xs px-3 py-1 rounded-lg bg-gray-100 dark:bg-slate-800 opacity-70 max-w-xs truncate border-l-2 border-blue-500 cursor-pointer hover:opacity-100`}
                    onClick={() => onReplyClick && onReplyClick(message.replyTo._id)}
                >
                    {t('chat.replyingTo')}: {message.replyTo.content}
                </div>
            )}
            
            <div className="flex items-end gap-2 max-w-[85%] md:max-w-[70%]">
                <div 
                    className={`relative p-3 rounded-2xl shadow-sm ${
                        isMe 
                        ? 'rounded-tr-none bg-blue-500 text-white' 
                        : 'rounded-tl-none bg-gray-100 dark:bg-slate-800 text-gray-900 dark:text-gray-100'
                    }`}
                    onContextMenu={(e) => {
                        e.preventDefault()
                        setContextMenu({ x: e.clientX, y: e.clientY })
                    }}
                >
                    {message.type === 'image' && message.mediaUrl && (
                        <div className="relative group/img cursor-pointer" onClick={() => onImageClick && onImageClick(getMediaUrl(message.mediaUrl))}>
                            <img src={getMediaUrl(message.mediaUrl)} alt="attachment" className="rounded-lg mb-2 max-h-60 w-full object-cover" />
                            <div className="absolute inset-0 bg-black/20 opacity-0 group-hover/img:opacity-100 transition-opacity flex items-center justify-center rounded-lg">
                                <ZoomIn className="text-white w-6 h-6" />
                            </div>
                        </div>
                    )}
                    
                    {message.type === 'video' && message.mediaUrl && (
                        <video controls src={getMediaUrl(message.mediaUrl)} className="rounded-lg mb-2 max-h-60 w-full bg-black" />
                    )}
                    
                    {message.type === 'audio' && message.mediaUrl && (
                        <audio controls src={getMediaUrl(message.mediaUrl)} className="mb-2" />
                    )}

                    {message.type === 'file' && message.mediaUrl && (
                        <a 
                            href={getMediaUrl(message.mediaUrl)} 
                            target="_blank" 
                            rel="noopener noreferrer" 
                            className="flex items-center gap-3 p-3 bg-gray-50 dark:bg-slate-700/50 rounded-lg mb-2 hover:bg-gray-100 dark:hover:bg-slate-700 transition-colors"
                        >
                            <div className="w-10 h-10 rounded-lg bg-blue-100 flex items-center justify-center text-blue-600">
                                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="w-5 h-5"><path d="M14.5 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V7.5L14.5 2z"/><polyline points="14 2 14 8 20 8"/></svg>
                            </div>
                            <div className="flex-1 min-w-0">
                                <p className="font-medium text-sm truncate">{message.fileName || 'Document'}</p>
                                <p className="text-xs text-gray-500">{(message.fileSize / 1024).toFixed(1)} KB</p>
                            </div>
                        </a>
                    )}

                    {(message.type === 'text' || !message.type) && (
                        <p className="text-sm whitespace-pre-wrap" dir="auto">{message.content}</p>
                    )}
                </div>
                
                <button 
                    onClick={() => onReply && onReply(message)}
                    className="md:opacity-0 md:group-hover:opacity-100 opacity-100 p-1 rounded-full hover:bg-gray-100 dark:hover:bg-slate-800 text-gray-400 transition-opacity"
                    title={t('chat.reply')}
                >
                    <Reply className="w-4 h-4" />
                </button>
            </div>
            <span className="text-xs text-gray-400 mt-1 px-1">{new Date(message.createdAt).toLocaleTimeString([], {hour: '2-digit', minute: '2-digit'})}</span>

            {/* Context Menu */}
            {contextMenu && (
                <>
                    <div className="fixed inset-0 z-40" onClick={() => setContextMenu(null)}></div>
                    <div 
                        className="fixed z-50 bg-white dark:bg-slate-800 shadow-xl rounded-lg border dark:border-slate-700 py-1 w-48"
                        style={{ top: Math.min(contextMenu.y, window.innerHeight - 200), left: Math.min(contextMenu.x, window.innerWidth - 200) }}
                    >
                        <button 
                            className="w-full text-left px-4 py-2 text-sm hover:bg-gray-100 dark:hover:bg-slate-700 flex items-center gap-2"
                            onClick={() => { 
                                onReply && onReply(message)
                                setContextMenu(null)
                            }}
                        >
                            <Reply className="w-4 h-4" /> {t('chat.reply')}
                        </button>
                        <button 
                            className="w-full text-left px-4 py-2 text-sm hover:bg-gray-100 dark:hover:bg-slate-700 flex items-center gap-2 text-red-500"
                            onClick={() => {
                                onDelete && onDelete(message._id, false)
                                setContextMenu(null)
                            }}
                        >
                            <Trash2 className="w-4 h-4" /> {t('chat.deleteForMe')}
                        </button>
                        {isMe && (
                            <button 
                                className="w-full text-left px-4 py-2 text-sm hover:bg-gray-100 dark:hover:bg-slate-700 flex items-center gap-2 text-red-500"
                                onClick={() => {
                                    onDelete && onDelete(message._id, true)
                                    setContextMenu(null)
                                }}
                            >
                                <Trash2 className="w-4 h-4" /> {t('chat.deleteForEveryone')}
                            </button>
                        )}
                    </div>
                </>
            )}
        </div>
    )
}

export default MessageBubble
